content_list.content:
Perfecto, ya revisé el estado actual real del proyecto con `index.js` y `session-manager.js`.

## Auditoría rápida del estado actual

### Lo que está bien y nos permite agregar anti-ban sin romper nada

1. **`index.js` está limpio**
   - Solo inicializa Express, Socket.IO, rutas, scheduler y restauración.
   - No toca WhatsApp directamente.
   - Respeta la arquitectura.

2. **`session-manager.js` es efectivamente el único punto donde se crea `new Client()`**
   - Esto es clave.
   - Respeta el **ADR-001**.
   - Significa que podemos agregar una capa de proxy/anti-ban **solo tocando este módulo**, sin ensuciar el resto del sistema.

3. **La arquitectura actual soporta multi-instancia**
   - Ya tenés `clients`, `sessions`, restauración, locks, estados, etc.
   - Se puede asignar configuración de red por instancia.

4. **Actualmente no existe ninguna capa anti-ban**
   - No veo proxy por instancia.
   - No veo humanización de envío.
   - No veo límites de calentamiento.
   - La reanudación automática de campañas puede ser peligrosa si el scheduler envía muy rápido.

---

# Conclusión importante

## Sí, se puede agregar una capa anti-ban por IP

Pero **no te conviene usar una VPN global de máquina** para múltiples cuentas.

### Por qué

Si ponés una VPN a nivel servidor/máquina:

- Todas tus instancias de WhatsApp salen por la misma IP.
- Si WhatsApp marca esa IP, puede afectar a todas las cuentas.
- Si la IP es de datacenter o VPN comercial, WhatsApp suele castigarla.
- Si la IP cambia constantemente, peor.

Para tu sistema multi-cuenta, lo correcto es:

> **Cada instancia de WhatsApp debe tener su propia IP fija, preferentemente residencial, del mismo país del número.**

Eso se implementa mejor con **proxies por instancia**, no con una VPN general.

---

# Dónde se debe implementar en tu código actual

El punto exacto está acá en `session-manager.js`:

```js
const client = new Client({
    authStrategy: new LocalAuth({
        clientId: instanceId,
        dataPath: SESSIONS_DIR
    }),
    puppeteer: {
        headless: true,
        executablePath: findChromePath(),
        timeout: 60000,
        protocolTimeout: 60000,
        args: [
            '--no-sandbox',
            '--disable-setuid-sandbox',
            '--disable-dev-shm-usage',
            '--disable-gpu',
            '--disable-crash-reporter',
            '--disable-breakpad',
            '--no-crash-upload'
        ]
    }
});
```

Ahí es donde se puede inyectar el proxy respetando tu arquitectura.

---

# Implementación recomendada

Te propongo agregar una capa nueva:

```text
managers/proxy-manager.js
data/proxies.json
```

Y modificar únicamente:

```text
services/session-manager.js
```

Esto mantiene limpio el diseño:

- `session-manager.js` sigue siendo el único que crea `new Client()`.
- El proxy es configuración de infraestructura/instancia.
- No se mezcla con CRM.
- No se mezcla con campañas.
- No se mezcla con IA.

---

# 1. Nuevo archivo: `managers/proxy-manager.js`

Creá la carpeta `managers` si todavía no existe y agregá este archivo.

```js
'use strict';

/**
 * MdI MultiWA
 * managers/proxy-manager.js
 * v1.0.0
 *
 * Responsabilidad:
 * - Administrar proxies por instancia.
 * - Proveer configuración de red a SessionManager.
 * - No conoce WhatsApp.
 * - No conoce CRM.
 * - No conoce campañas.
 */

const fs = require('fs');
const path = require('path');

const DATA_DIR = path.join(__dirname, '..', 'data');
const PROXY_FILE = path.join(DATA_DIR, 'proxies.json');

//==============================================================
// UTILIDADES
//==============================================================

function ensureDataDir() {
    if (!fs.existsSync(DATA_DIR)) {
        fs.mkdirSync(DATA_DIR, { recursive: true });
    }
}

function ensureFile() {
    ensureDataDir();

    if (!fs.existsSync(PROXY_FILE)) {
        const inicial = {
            instances: {}
        };

        fs.writeFileSync(
            PROXY_FILE,
            JSON.stringify(inicial, null, 2),
            'utf8'
        );
    }
}

function load() {
    ensureFile();

    try {
        return JSON.parse(fs.readFileSync(PROXY_FILE, 'utf8'));
    } catch (err) {
        console.warn('⚠ proxies.json corrupto o ilegible. Se usa configuración vacía.');
        return { instances: {} };
    }
}

function save(data) {
    ensureFile();

    fs.writeFileSync(
        PROXY_FILE,
        JSON.stringify(data, null, 2),
        'utf8'
    );
}

function normalizeProxy(value) {
    if (!value) return null;

    const proxy = String(value).trim();

    return proxy.length ? proxy : null;
}

//==============================================================
// PARSER DE PROXY
//==============================================================

function parseProxy(raw) {
    const normalized = normalizeProxy(raw);

    if (!normalized) return null;

    let value = normalized;

    // Si viene sin protocolo, asumimos http
    if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(value)) {
        value = `http://${value}`;
    }

    try {
        const url = new URL(value);

        const protocol = url.protocol.replace(':', '').toLowerCase();

        let defaultPort = '80';

        if (protocol.startsWith('socks')) {
            defaultPort = '1080';
        } else if (protocol === 'https') {
            defaultPort = '443';
        }

        return {
            raw: normalized,
            protocol,
            host: url.hostname,
            port: url.port || defaultPort,
            username: url.username ? decodeURIComponent(url.username) : null,
            password: url.password ? decodeURIComponent(url.password) : null
        };
    } catch (err) {
        console.warn(`⚠ Proxy inválido: ${normalized}`);
        return null;
    }
}

//==============================================================
// API PÚBLICA
//==============================================================

/**
 * Devuelve el proxy crudo asignado a una instancia.
 * Ejemplo:
 * http://user:pass@1.2.3.4:8080
 */
function getProxyParaInstancia(instanceId) {
    const data = load();

    const proxy =
        data?.instances?.[instanceId] ||
        data?.default ||
        process.env.DEFAULT_PROXY ||
        null;

    return normalizeProxy(proxy);
}

/**
 * Devuelve el argumento compatible con Chromium/Puppeteer.
 * Ejemplo:
 * --proxy-server=http://1.2.3.4:8080
 */
function getProxyArg(instanceId) {
    const raw = getProxyParaInstancia(instanceId);

    if (!raw) return null;

    const parsed = parseProxy(raw);

    if (!parsed) return null;

    if (parsed.protocol.startsWith('socks')) {
        return `--proxy-server=socks5://${parsed.host}:${parsed.port}`;
    }

    return `--proxy-server=http://${parsed.host}:${parsed.port}`;
}

/**
 * Devuelve credenciales si el proxy usa usuario/contraseña.
 */
function getProxyCredentials(instanceId) {
    const raw = getProxyParaInstancia(instanceId);

    if (!raw) return null;

    const parsed = parseProxy(raw);

    if (!parsed) return null;

    if (!parsed.username && !parsed.password) return null;

    return {
        username: parsed.username || '',
        password: parsed.password || ''
    };
}

/**
 * Guarda o elimina un proxy para una instancia.
 */
function setProxyParaInstancia(instanceId, proxyUrl) {
    const data = load();

    if (!data.instances || typeof data.instances !== 'object') {
        data.instances = {};
    }

    const normalized = normalizeProxy(proxyUrl);

    if (normalized) {
        data.instances[instanceId] = normalized;
    } else {
        delete data.instances[instanceId];
    }

    save(data);

    return true;
}

/**
 * Devuelve todos los proxies configurados.
 */
function getAllProxies() {
    const data = load();

    return {
        default: data.default || null,
        instances: data.instances || {}
    };
}

/**
 * Enmascara el proxy para logs.
 * No debe mostrar usuario/contraseña.
 */
function maskProxy(raw) {
    const parsed = parseProxy(raw);

    if (!parsed) {
        return 'proxy-configurado';
    }

    return `${parsed.protocol}://${parsed.host}:${parsed.port}`;
}

//==============================================================
// EXPORT
//==============================================================

module.exports = {
    getProxyParaInstancia,
    getProxyArg,
    getProxyCredentials,
    setProxyParaInstancia,
    getAllProxies,
    maskProxy
};
```

---

# 2. Nuevo archivo: `data/proxies.json`

Este archivo no debe contener datos del CRM. Es infraestructura.

```json
{
  "instances": {
    "NOMBRE_DE_INSTANCIA_1": "http://usuario:password@ip:puerto",
    "NOMBRE_DE_INSTANCIA_2": "socks5://usuario:password@ip:puerto"
  }
}
```

Ejemplo real:

```json
{
  "instances": {
    "cuenta-principal": "http://192.168.1.50:8080",
    "cuenta-secundaria": "socks5://10.0.0.10:1080"
  }
}
```

Importante:

```gitignore
data/proxies.json
```

No subas proxies con credenciales a GitHub.

---

# 3. Modificación en `session-manager.js`

Ahora vamos al archivo real que me pasaste.

## 3.1. Agregar require

Arriba, cerca de estos requires:

```js
const {
    obtenerInstanciasPorUsuario,
    obtenerTodosLosUsuarios,
    guardarInstancia,
    eliminarInstancia
} = require('./instancias-persistencia');

const socketNotifier =
    require('./socket-notifier');
```

Agregás:

```js
const proxyManager = require('../managers/proxy-manager');
```

Si tu carpeta `managers` está al mismo nivel que `services`, queda así:

```text
project-root/
  managers/
    proxy-manager.js
  services/
    session-manager.js
```

---

## 3.2. Reemplazar la creación del cliente

Buscá esta parte exacta:

```js
 //----------------------------------------------------------
 // Crear Cliente
 //----------------------------------------------------------
 const client = new Client({
     authStrategy: new LocalAuth({
         clientId: instanceId,
         dataPath: SESSIONS_DIR
     }),
     puppeteer: {
         headless: true,
         executablePath: findChromePath(),
         timeout: 60000,
         protocolTimeout: 60000,
         args: [
             '--no-sandbox',
             '--disable-setuid-sandbox',
             '--disable-dev-shm-usage',
             '--disable-gpu',
             '--disable-crash-reporter',
             '--disable-breakpad',
             '--no-crash-upload'
         ]
     }
 });
```

Y reemplazala por esto:

```js
 //----------------------------------------------------------
 // Capa anti-ban: proxy por instancia
 //----------------------------------------------------------
 const proxyRaw = proxyManager.getProxyParaInstancia(instanceId);
 const proxyArg = proxyManager.getProxyArg(instanceId);
 const proxyCredentials = proxyManager.getProxyCredentials(instanceId);

 const basePuppeteerArgs = [
     '--no-sandbox',
     '--disable-setuid-sandbox',
     '--disable-dev-shm-usage',
     '--disable-gpu',
     '--disable-crash-reporter',
     '--disable-breakpad',
     '--no-crash-upload',
     '--disable-blink-features=AutomationControlled'
 ];

 const puppeteerArgs = proxyArg
     ? [...basePuppeteerArgs, proxyArg]
     : basePuppeteerArgs;

 if (proxyRaw) {
     console.log(
         `🌍 Proxy configurado para ${instanceId}: ${proxyManager.maskProxy(proxyRaw)}`
     );
 }

 //----------------------------------------------------------
 // Crear Cliente
 //----------------------------------------------------------
 const client = new Client({
     authStrategy: new LocalAuth({
         clientId: instanceId,
         dataPath: SESSIONS_DIR
     }),
     puppeteer: {
         headless: true,
         executablePath: findChromePath(),
         timeout: 60000,
         protocolTimeout: 60000,
         args: puppeteerArgs
     }
 });
```

---

## 3.3. Soporte para proxies con usuario/contraseña

Opcional, pero útil si tu proxy usa autenticación.

Después de crear el cliente y registrarlo, por ejemplo después de:

```js
 //----------------------------------------------------------
 // Registrar cliente
 //----------------------------------------------------------
 clients.set(
     instanceId,
     client
 );
 userSession.instances.get(
     instanceId
 ).client = client;
```

Agregás:

```js
 //----------------------------------------------------------
 // Autenticación de proxy si corresponde
 //----------------------------------------------------------
 if (proxyCredentials) {
     client.once('authenticated', async () => {
         try {
             if (client.pupPage) {
                 await client.pupPage.authenticate(proxyCredentials);
                 console.log(
                     `🔐 Proxy autenticado para ${instanceId}`
                 );
             }
         } catch (err) {
             console.warn(
                 `⚠ No se pudo autenticar el proxy para ${instanceId}:`,
                 err.message
             );
         }
     });
 }
```

Importante: para producción, lo más estable suele ser usar proxies con IP autorizada, sin usuario/contraseña. Muchos proveedores residenciales permiten “IP whitelist”.

---

# 4. Qué significa esto en la práctica

Con este cambio:

- Cada instancia puede salir por una IP distinta.
- No tenés que tocar el CRM.
- No rompés `index.js`.
- Respetás el ADR-001.
- Podés evolucionar luego a un panel de configuración de proxies.

---

# 5. Recomendación crítica sobre la VPN

## Si usás VPN global

Funciona, pero no es lo ideal para multi-cuenta.

Ejemplo:

```text
Todas tus cuentas → misma VPN → misma IP
```

Riesgo:

```text
Si WhatsApp castiga esa IP, te puede salpicar a todas las cuentas.
```

## Si usás proxies por instancia

Ejemplo:

```text
Instancia A → IP residencial A
Instancia B → IP residencial B
Instancia C → IP residencial C
```

Esto es mucho más sano para tu sistema.

---

# 6. Tipo de IP recomendada

Para reducir riesgo, la IP debería ser:

| Tipo de IP | Recomendación |
|---|---|
| VPN gratuita | No recomendada |
| VPN comercial compartida | Riesgosa |
| Datacenter | Muy riesgosa |
| Residencial compartida | Riesgosa si rota |
| Residencial fija/sticky | Recomendada |
| Residencial del mismo país del número | Ideal |

Ejemplo bueno:

```text
Número argentino → IP residencial argentina fija
Número mexicano → IP residencial mexicana fija
```

Ejemplo malo:

```text
Número argentino → IP de Estados Unidos que cambia cada 5 minutos
```

---

# 7. Reglas anti-ban que tenés que respetar

La IP es solo una parte. WhatsApp no banea solo por IP. Banea por comportamiento.

## Reglas mínimas

### 1. Una IP fija por número

Nunca rotar IP por mensaje.

Malo:

```text
Mensaje 1 → IP A
Mensaje 2 → IP B
Mensaje 3 → IP C
```

Bueno:

```text
Instancia A → siempre IP A
```

---

### 2. No compartir IP entre cuentas

Malo:

```text
Cuenta 1 → IP 1.2.3.4
Cuenta 2 → IP 1.2.3.4
Cuenta 3 → IP 1.2.3.4
```

Bueno:

```text
Cuenta 1 → IP 1.2.3.4
Cuenta 2 → IP 5.6.7.8
Cuenta 3 → IP 9.10.11.12
```

---

### 3. Calentamiento de cuentas

Si la cuenta es nueva o estuvo fría, no puede mandar cientos de mensajes de golpe.

Ejemplo conservador:

| Día | Mensajes sugeridos |
|---|---:|
| 1 | 20-30 |
| 2 | 40-50 |
| 3 | 60-80 |
| 4 | 80-120 |
| 5+ | según calidad de cuenta |

Esto debería implementarse en el scheduler de campañas.

---

### 4. Delays aleatorios

Nunca enviar mensajes a intervalo fijo.

Malo:

```text
Cada 2 segundos exactos
```

Bueno:

```text
Entre 7 y 23 segundos aleatorios
```

---

### 5. Simular escritura

Antes de enviar:

```text
typing...
```

Duración aproximada según largo del mensaje.

---

### 6. Variaciones de mensaje

No mandar exactamente el mismo texto a 1000 personas.

Conviene tener plantillas con variaciones:

```text
Hola {nombre}, te escribo por...
Buen día {nombre}, quería consultarte...
Hola {nombre}, cómo estás? Te contacto por...
```

---

# 8. Lo que falta revisar para anti-ban real

Con el proxy ya cubrís la parte de IP.

Pero si te están baneando, casi seguro también hay que revisar el envío de campañas.

Para eso necesito ver estos archivos:

```text
services/campaign-scheduler.js
routes/api-envio.js
routes/api-carga.js
services/inbound-message-handler.js
```

Especialmente:

```text
campaign-scheduler.js
```

Porque en tu `session-manager.js` veo esto:

```js
const scheduler = require('./campaign-scheduler');
```

Y también veo reanudación automática de campañas:

```js
await scheduler.iniciar(instanceId);
```

Ese módulo es crítico. Si manda rápido, WhatsApp te detecta aunque cambies IP.

---

# 9. ADR nuevo recomendado

Como tu documentación exige registrar decisiones arquitectónicas, correspondería agregar:

```md
ADR-010
Proxy por instancia para reducción de riesgo de suspensión
Estado
Propuesto
Fecha
Fecha actual
Autor
Nombre del responsable

Problema
Las cuentas de WhatsApp pueden ser suspendidas por detección de comportamiento automatizado, asociación de IPs o uso de IPs de baja reputación.
Actualmente todas las instancias salen por la misma IP del servidor/máquina.

Alternativas
1. Usar una VPN global a nivel sistema operativo.
2. No modificar la IP.
3. Asignar un proxy dedicado por instancia desde SessionManager.

Decisión
Se implementará soporte de proxy por instancia.
Cada instancia podrá tener una IP residencial fija asociada.
La configuración se almacenará en data/proxies.json.
La inyección del proxy se realizará únicamente en session-manager.js durante la creación del Client(), respetando ADR-001.

Consecuencias
✔ Permite separar IPs por cuenta.
✔ Reduce riesgo de asociación entre instancias.
✔ Permite usar IPs residenciales fijas.
✔ No modifica CRM ni campañas.
✘ Requiere gestión segura de credenciales.
✘ Los proxies residenciales tienen costo operativo.
✘ El proxy por sí solo no elimina el riesgo de suspensión.
```

---

# 10. Mi recomendación práctica inmediata

Hacelo en dos fases.

## Fase 1: Proxy por instancia

Implementar lo que te pasé arriba:

```text
managers/proxy-manager.js
data/proxies.json
patch en session-manager.js
```

Esto te permite probar con una cuenta sin tocar todo lo demás.

---

## Fase 2: Capa de humanización

Después agregamos una capa para campañas:

```text
delays aleatorios
typing
límites diarios
calentamiento
variaciones de mensaje
```

Eso probablemente se llame algo como:

```text
services/outbound-guard.js
```

o

```text
services/humanizer-service.js
```

Pero para hacerlo bien tengo que ver el scheduler actual.

---

# Respuesta corta

Sí, se puede agregar una capa anti-ban por IP en tu proyecto actual.

La forma correcta no es una VPN global para todas las cuentas, sino:

> **Proxies fijos por instancia, inyectados únicamente en `session-manager.js`.**

Con los archivos que me pasaste, es totalmente viable y se puede hacer respetando la arquitectura actual.

Si querés, en el próximo paso te preparo el patch completo listo para copiar y pegar, o directamente revisamos `campaign-scheduler.js` para atacar también el comportamiento de envío, que suele ser la causa principal de baneos.

Ya revisé `anti-baneo.js` junto con `session-manager.js`, `index.js` y la arquitectura que me pasaste antes.

## Diagnóstico rápido

Este módulo está pensado como **anti-ban conductual**, es decir: límites de envío, pausas, horarios, rotación de mensajes, cooldowns, etc.

Eso está muy bien, porque el anti-ban real no es solo IP. Pero hay varios puntos importantes:

---

# 1. Este módulo no cubre la parte de IP

`anti-baneo.js` controla:

- horarios
- límites por hora
- límites por día
- límites por semana
- límites por franja
- pausas largas
- errores consecutivos
- rotación de mensajes
- contactos respondidos

Pero **no maneja proxy, VPN ni IP**.

Así que actualmente tenés dos capas separadas:

```text
Capa conductual
anti-baneo.js

Capa de red / IP
pendiente de implementar
```

Para reducir baneos, necesitás las dos.

---

# 2. En el código que subiste hay un posible error de sintaxis

En `getFranjaActual()` aparece esto:

```js
if (hora  >= 6  & & hora  < 9) return 0;
if (hora  >= 9  & & hora  < 12) return 1;
if (hora  >= 12  & & hora  < 15) return 2;
if (hora  >= 15  & & hora  < 18) return 3;
if (hora  >= 18  & & hora  < 21) return 4;
```

Ese `& &` con espacios no es JavaScript válido. Debería ser:

```js
if (hora >= 6 && hora < 9) return 0;
if (hora >= 9 && hora < 12) return 1;
if (hora >= 12 && hora < 15) return 2;
if (hora >= 15 && hora < 18) return 3;
if (hora >= 18 && hora < 21) return 4;
```

Si en tu proyecto real está `&&` sin espacios, perfecto. Pero si el archivo tiene literalmente `& &`, Node debería fallar al cargar el módulo.

---

# 3. Hay un bug importante en `controlarTasaEnvio`

Actualmente tenés:

```js
async function controlarTasaEnvio(instanceId) {
    while (!puedeEnviarMas(instanceId)) {
        actualizarContadores(instanceId);
        const espera = Math.max(1000, obtenerTiempoRestante(instanceId) * 1000);
        console.log(`⏳ ${obtenerMotivoPausa(instanceId)}. Esperando ${Math.round(espera / 1000)}s...`);
        await new Promise(r => setTimeout(r, espera));
    }

    incrementarMensajesHora(instanceId);
}
```

El problema:

```text
Solo incrementa mensajesEstaHora.
```

Pero `puedeEnviarMas()` también controla:

```js
c.mensajesHoy < CONFIG.MAX_MENSAJES_DIA
c.mensajesEstaSemana < CONFIG.MAX_MENSAJES_SEMANA
c.mensajesEstaFranja < CONFIG.MAX_MENSAJES_FRANJA
```

Si solo incrementás la hora, los límites diarios, semanales y por franja pueden no funcionar bien salvo que el scheduler llame manualmente a:

```js
incrementarMensajesHoy(instanceId);
incrementarMensajesSemana(instanceId);
incrementarMensajesFranja(instanceId);
```

Si el scheduler no hace eso, esos límites quedan flojos.

---

## Corrección recomendada

Agregá una función central:

```js
function registrarEnvio(instanceId) {
    actualizarContadores(instanceId);

    const c = obtenerContador(instanceId);

    c.mensajesEstaHora++;
    c.mensajesHoy++;
    c.mensajesEstaSemana++;
    c.mensajesEstaFranja++;
    c.ultimoEnvio = Date.now();
}
```

Y reemplazá `controlarTasaEnvio` por esto:

```js
async function controlarTasaEnvio(instanceId) {
    actualizarContadores(instanceId);

    while (!puedeEnviarMas(instanceId)) {
        actualizarContadores(instanceId);

        const espera = Math.max(1000, obtenerTiempoRestante(instanceId) * 1000);

        console.log(
            `⏳ ${obtenerMotivoPausa(instanceId)}. ` +
            `Esperando ${Math.round(espera / 1000)}s...`
        );

        await new Promise(r => setTimeout(r, espera));
    }

    registrarEnvio(instanceId);
}
```

Y exportala:

```js
module.exports = {
    // ...exports actuales
    registrarEnvio
};
```

---

# 4. Los contadores son volátiles

Actualmente los contadores viven acá:

```js
const contadores = new Map();
```

Eso significa:

```text
Si reiniciás Node, los contadores se reinician.
```

Y esto es peligroso porque tu `session-manager.js` reanuda campañas automáticamente:

```js
console.log(
    `🔄 Campaña activa detectada (${instanceId}) — se reanudará automáticamente`
);
```

Entonces puede pasar esto:

```text
1. La instancia llegó al límite diario.
2. Se reinicia el servidor.
3. Se borran los contadores de memoria.
4. La campaña se reanuda.
5. WhatsApp ve actividad nuevamente sin límite.
```

Para anti-ban serio, los contadores deberían persistirse en algo como:

```text
data/contadores-antibaneo.json
```

Eso se puede hacer sin romper la arquitectura, pero conviene hacerlo con cuidado para no escribir en disco constantemente.

