Contenido:

```js
'use strict';

/**
 * MdI MultiWA
 * services/human-sender.js
 * v1.0.0
 *
 * Responsabilidad:
 * - Simular comportamiento humano antes de enviar mensajes.
 * - Respetar límites de anti-baneo.
 * - Simular escritura.
 * - Agregar pausas aleatorias.
 * - Registrar errores de envío.
 *
 * No conoce CRM.
 * No conoce campañas.
 * No conoce persistencia.
 */

const antiBaneo = require('../config/anti-baneo');

//==============================================================
// UTILIDADES
//==============================================================

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function rand(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

//==============================================================
// SIMULACIÓN DE ESCRITURA
//==============================================================

/**
 * Calcula cuánto tiempo debería tardar un humano en escribir el texto.
 * No debe ser eterno, pero tampoco instantáneo.
 */
function calcularDuracionEscritura(texto) {
    const clean = String(texto || '').trim();

    if (!clean) return 0;

    const words = clean.split(/\s+/).length;

    // Velocidad humana simulada: 18-45 palabras por minuto
    const wpm = rand(18, 45);

    let seconds = (words / wpm) * 60;

    // Mínimo 1.2 segundos, máximo 15 segundos
    seconds = clamp(seconds, 1.2, 15);

    // Ruido aleatorio adicional
    seconds += rand(300, 2500) / 1000;

    return seconds * 1000;
}

/**
 * Simula estado "escribiendo..." de forma más humana.
 */
async function simularEscritura(client, chatId, texto) {
    if (!client || !chatId || !texto) return;

    try {
        await client.sendStateTyping(chatId);

        const totalMs = calcularDuracionEscritura(texto);

        if (!totalMs || totalMs <= 0) return;

        // Simulamos pequeñas pausas mentales / bloques de escritura
        const chunkSize = rand(18, 42);
        const chunks = Math.max(1, Math.ceil(String(texto).length / chunkSize));

        const baseChunkMs = totalMs / chunks;

        for (let i = 0; i < chunks; i++) {
            const jitter = rand(-350, 800);
            const waitChunk = Math.max(200, baseChunkMs + jitter);

            await sleep(waitChunk);

            // Refrescar estado de escritura ocasionalmente
            if (i > 0 && i % 2 === 0) {
                try {
                    await client.sendStateTyping(chatId);
                } catch (err) {
                    // Ignorar: no debe romper el envío
                }
            }
        }
    } catch (err) {
        console.warn('⚠ No se pudo simular escritura humana:', err.message);
    }
}

/**
 * Pausa previa como si la persona estuviera pensando.
 */
async function esperarPensamiento() {
    await sleep(rand(1200, 6500));
}

/**
 * Pausa posterior al envío usando la configuración anti-ban.
 */
async function esperarDespuesDeEnviar(instanceId) {
    const pausa = antiBaneo.getPausaAleatoria(instanceId);

    console.log(
        `😴 Pausa post-envío para ${instanceId}: ` +
        `${Math.round(pausa / 1000)}s`
    );

    await sleep(pausa);
}

