//==============================================================
// OBTENER INSTANCIAS DEL USUARIO
//==============================================================
function getUserInstances(userId){
    const session =
        sessions.get(userId);
    const enMemoria =
        session
            ? [...session.instances.values()]
            : [];
    const idsEnMemoria =
        new Set(
            enMemoria.map(i => i.id)
        );
    const persistidas =
        obtenerInstanciasPorUsuario(userId);
    const pendientes =
        persistidas
            .filter(
                p => !idsEnMemoria.has(p.id)
            )
            .map(p => ({
                id: p.id,
                numero: p.numero || '',
                listo: p.listo || false,
                estado: null,
                iniciada: false
            }));
    return [
        ...enMemoria.map(
            i => ({
                ...i,
                iniciada: true
            })
        ),
        ...pendientes
    ];
}

//==============================================================
// RESUMEN DE INSTANCIAS (PARA SOCKET.IO)
//==============================================================
function getUserInstancesResumen(userId){
    return getUserInstances(userId).map(
        i => ({
            id: i.id,
            numero: i.numero || '',
            listo: !!i.listo,
            iniciada: i.iniciada !== false
        })
    );
}
function setActiveInstance(
    userId,
    instanceId
){
    const session =
        sessions.get(userId);
    if(!session){
        return false;
    }
    if(
        !session.instances.has(instanceId)
    ){
        return false;
    }
    session.activeId = instanceId;
    return true;
}

//==============================================================
// GUARDAR INSTANCIA EN SESIÓN
//==============================================================
function guardarInstanciaSesion(
    userId,
    instanceId,
    datos
){
    const session =
        sessions.get(userId);
    if(!session){
        return false;
    }
    const actual =
        session.instances.get(instanceId);
    if(!actual){
        return false;
    }
    Object.assign(
        actual,
        datos
    );
    session.instances.set(
        instanceId,
        actual
    );
    // FIX: guardarInstancia() es la función importada de
    // instancias-persistencia.
    guardarInstancia(
        userId,
        instanceId,
        actual
    );
    return true;
}

