async function shutdown() {
    console.log(
        `🛑 Cerrando ${clients.size} cliente(s) de WhatsApp...`
    );
    const destrucciones =
        [...clients.entries()].map(
            async ([instanceId, client]) => {
                try {
                    await gracefulDestroy(client);
                    console.log(
                        `✅ Cliente cerrado: ${instanceId}`
                    );
                }
                catch (err) {
                    console.warn(
                        `⚠ Error cerrando ${instanceId}:`,
                        err.message
                    );
                }
            }
        );
    await Promise.allSettled(
        destrucciones
    );
    clients.clear();
}

