El problema de fondo es un **bug conocido de la librería `whatsapp-web.js`**: cuando un número no está en la agenda del celular, WhatsApp Web le asigna un ID temporal interno llamado `@lid`. La librería intenta enviar el mensaje a ese `@lid`, pero su sistema interno de caché ("memoize") falla y crashea.

### ✅ La Solución Definitiva (Sin tocar el celular)

La forma de vencer este bug **programáticamente** es:
1. Intentar resolver el número con `getNumberId`.
2. **Si la librería nos devuelve un `@lid`, lo ignoramos por completo** y forzamos manualmente el formato clásico `${numero}@c.us` para el envío.
3. Agregar una micro-pausa de 800ms antes de enviar, para darle tiempo al navegador oculto (Puppeteer) de procesar el chat en segundo plano sin crashear.

Reemplazá **solamente la función `enviarMensaje`** en tu archivo `services/campaign-runner.js` por esta versión blindada:

```javascript
//==============================================================
// ENVIAR MENSAJE (Versión Anti-@lid Definitiva)
//==============================================================
async function enviarMensaje(instanceId, client, estado, contacto, numero) {
    try {
        console.log(`📤 Enviando a ${numero}...`);

        // 1. Determinar el destino. Por defecto, forzamos el formato clásico @c.us
        let destino = `${numero}@c.us`;

        try {
            const chatInfo = await client.getNumberId(numero);
            if (chatInfo && chatInfo._serialized) {
                // Si WhatsApp nos devuelve un @lid, LO IGNORAMOS.
                // Usar @lid en sendMessage es lo que causa el bug de "memoize".
                if (chatInfo._serialized.includes('@lid')) {
                    console.log(`⚠️ WhatsApp devolvió @lid para ${numero}. Forzando @c.us para evitar crash.`);
                    destino = `${numero}@c.us`;
                } else {
                    destino = chatInfo._serialized;
                }
            }
        } catch (err) {
            // Si getNumberId falla, no nos detenemos. Usamos el fallback @c.us.
            console.log(`⚠️ No se pudo resolver el ID de ${numero}. Usando formato @c.us directo.`);
        }

        const mensajes = (estado.mensajesGuardados || []).filter(Boolean);
        if (mensajes.length === 0) {
            return { tipo: RESULTADO.ERROR, motivo: "No hay mensajes cargados" };
        }

        const mensajeBase = antiBan.seleccionarMensaje(instanceId, mensajes);
        const texto = procesarSpintax(reemplazarVariables(mensajeBase, contacto, estado));

        // 2. Simulación de escritura (ya protegida en formateo.js)
        try {
            await simularEscrituraHumana(client, destino, texto);
        } catch (typingErr) {
            console.warn(`⚠️ Falló la animación de escritura: ${typingErr.message}`);
        }

        // 3. Micro-pausa estratégica: le da tiempo a WhatsApp Web de 
        // montar el chat en caché antes de la inyección del mensaje.
        await new Promise(r => setTimeout(r, 800));

        // 4. Enviar usando client.sendMessage directamente (más estable)
        const opcionesEnvio = { linkPreview: false };
        if (estado.imagenGuardada) {
            const archivo = path.join(__dirname, "..", "uploads", estado.imagenGuardada);
            if (fs.existsSync(archivo)) {
                const media = MessageMedia.fromFilePath(archivo);
                await client.sendMessage(destino, media, { caption: texto, linkPreview: false });
            } else {
                await client.sendMessage(destino, texto, opcionesEnvio);
            }
        } else {
            await client.sendMessage(destino, texto, opcionesEnvio);
        }

        return marcarExito(instanceId, estado, contacto, destino);
    }
    catch (err) {
        console.error("❌ Error en enviarMensaje:", err.message);

        // Si a pesar de todo salta el bug de memoize, lo capturamos 
        // para que la campaña NO se detenga y pase al siguiente.
        if (err.message && err.message.includes("memoize")) {
            console.log(`⚠️ [BUG LIBRERÍA] Falló por @lid en ${numero}. Se salta y continúa.`);
            return marcarError(instanceId, estado, contacto, "Fallo técnico de librería (ID @lid)");
        }

        if (err.message && (err.message.includes("Could not find the requested contact") || err.message.includes("not registered"))) {
            return marcarError(instanceId, estado, contacto, "El número no tiene WhatsApp");
        }

        return marcarError(instanceId, estado, contacto, err.message);
    }
}
```

### ¿Por qué esto sí va a funcionar con tu planilla?
1. **No requiere agenda**: El código toma el número de tu planilla, le agrega `@c.us` y se lo entrega a la librería.
2. **Neutraliza el `@lid`**: Si la librería intenta "corregir" el número y te devuelve un `@lid`, el código lo detecta, lo descarta y obliga al sistema a usar el formato clásico, que es el único que no crashea.
3. **La campaña no se frena**: Si un número está realmente corrupto o bloqueado a nivel de red, el `catch` lo marca como "Fallo técnico", espera 5 segundos (gracias a la configuración de `marcarError` que ya tenemos) y **pasa automáticamente al siguiente contacto de tu planilla**.

Guardá el cambio, reiniciá el servidor (`Ctrl + C` y `node index.js`) y probá con la misma planilla. Deberías ver en la consola el aviso `⚠️ WhatsApp devolvió @lid... Forzando @c.us` y luego el mensaje saliendo con éxito ✅.

