const sessionManager = require('./session-manager');
const fs = require('fs');
const path = require('path');
const { MessageMedia } = require('whatsapp-web.js');
const antiBan = require('../config/anti-baneo');
const { esBaja } = require('./bajas');
const {
    formatearNumeroWhatsApp,
    procesarSpintax,
    simularEscrituraHumana
} = require('./formateo');
const {
    getEstadoInstancia,
    guardarEstadoSeguro
} = require('../state/estado');

const RESULTADO = {
    OK: "OK",
    PAUSA: "PAUSA",
    BAJA: "BAJA",
    FINALIZADA: "FINALIZADA",
    ERROR: "ERROR"
};

function esErrorFrameDetached(err) {
    if (!err || !err.message) return false;
    return (
        err.message.includes('detached Frame') ||
        err.message.includes('Target closed') ||
        err.message.includes('Session closed') ||
        err.message.includes('Protocol error') ||
        err.message.includes('Navigation failed')
    );
}

async function run(instanceId) {
    const estado = getEstadoInstancia(instanceId);
    if (!estado) return { tipo: RESULTADO.ERROR, motivo: "Estado inexistente" };

    const client = sessionManager.getClient(instanceId);
    if (!client) return { tipo: RESULTADO.ERROR, motivo: "Cliente no conectado" };
    if (!client.info || !client.info.wid) return { tipo: RESULTADO.PAUSA, pausa: 3000 };
    if (!Array.isArray(estado.contactosCargados) || estado.contactosCargados.length === 0) {
        return { tipo: RESULTADO.ERROR, motivo: "No hay contactos" };
    }
    if (estado.actual >= estado.contactosCargados.length) {
        estado.enviando = false;
        estado.campanaFinalizada = true;
        guardarEstadoSeguro(instanceId);
        return { tipo: RESULTADO.FINALIZADA };
    }

    const contacto = estado.contactosCargados[estado.actual];
    return await procesarContacto(instanceId, client, estado, contacto);
}

async function procesarContacto(instanceId, client, estado, contacto) {
    if (!contacto) return { tipo: RESULTADO.ERROR, motivo: "Contacto inexistente" };

    const numero = formatearNumeroWhatsApp(contacto.numero || contacto.NUMERO || "");
    if (!numero) return marcarError(instanceId, estado, contacto, "Número inválido");

    if (esBaja(numero)) {
        contacto.estadoEnvio = "baja";
        contacto.fechaEnvio = new Date().toISOString();
        estado.actual++;
        guardarEstadoSeguro(instanceId);
        return { tipo: RESULTADO.BAJA };
    }

    if (antiBan.debeSaltarContactoRespondido(estado, numero, contacto.chatIdEnviado)) {
        contacto.estadoEnvio = "respondido";
        contacto.fechaEnvio = new Date().toISOString();
        estado.actual++;
        guardarEstadoSeguro(instanceId);
        return { tipo: RESULTADO.OK, pausa: 1000 };
    }

    const horarioOK = antiBan.esHorarioValido();
    const almuerzoOK = !antiBan.esHorarioAlmuerzo();
    const erroresOK = !antiBan.debePausarPorErrores(instanceId);

    if (!horarioOK || !almuerzoOK || !erroresOK) {
        return {
            tipo: RESULTADO.PAUSA,
            motivo: antiBan.obtenerMotivoPausa(instanceId),
            pausa: antiBan.obtenerTiempoRestante(instanceId) * 1000
        };
    }

    if (!antiBan.puedeEnviarMas(instanceId)) {
        return {
            tipo: RESULTADO.PAUSA,
            motivo: antiBan.obtenerMotivoPausa(instanceId),
            pausa: antiBan.obtenerTiempoRestante(instanceId) * 1000
        };
    }

    try {
        if (typeof client.getState === "function") {
            const estadoWA = await client.getState();
            if (['UNPAIRED', 'UNPAIRED_IDLE', 'CONFLICT', 'DISCONNECTED'].includes(estadoWA)) {
                return { tipo: RESULTADO.ERROR, motivo: `WhatsApp ${estadoWA}. Reconectá la sesión.` };
            }
        }
    } catch (err) {
        if (esErrorFrameDetached(err)) {
            estado.enviando = false;
            estado.pausado = true;
            guardarEstadoSeguro(instanceId);
            return { tipo: RESULTADO.ERROR, motivo: "WhatsApp desconectado (frame detached)." };
        }
    }

    const resultado = await enviarMensaje(instanceId, client, estado, contacto, numero);

    if (resultado.tipo === RESULTADO.ERROR && resultado._frameDetached) {
        await new Promise(resolve => setTimeout(resolve, 3000));
        const reintento = await enviarMensaje(instanceId, client, estado, contacto, numero);
        if (reintento.tipo !== RESULTADO.ERROR) return reintento;
        return resultado;
    }

    return resultado;
}

//==============================================================
// ENVIAR MENSAJE (Versión Ultra-Robusta v2.1)
//==============================================================
async function enviarMensaje(instanceId, client, estado, contacto, numero) {
    try {
        console.log(`📤 Enviando a ${numero}...`);

        // 1. Obtener el ID real que WhatsApp nos da (puede ser @lid o @c.us)
        const chatInfo = await client.getNumberId(numero);
        if (!chatInfo) {
            return marcarError(instanceId, estado, contacto, "Número inexistente en WhatsApp");
        }
        const destino = chatInfo._serialized;
        console.log(`✅ Chat ID resolvido: ${destino}`);

        const mensajes = (estado.mensajesGuardados || []).filter(Boolean);
        if (mensajes.length === 0) {
            return { tipo: RESULTADO.ERROR, motivo: "No hay mensajes cargados" };
        }

        const mensajeBase = antiBan.seleccionarMensaje(instanceId, mensajes);
        const texto = procesarSpintax(reemplazarVariables(mensajeBase, contacto, estado));

        // 2. Simulación de escritura (ya protegida contra @lid en formateo.js)
        try {
            await simularEscrituraHumana(client, destino, texto);
        } catch (typingErr) {
            console.warn(`⚠️ Falló la animación de escritura: ${typingErr.message}`);
        }

        const opcionesEnvio = { linkPreview: false };
        let enviadoConExito = false;

        // ==========================================================
        // INTENTO A: Usar el objeto Chat directamente (Más estable con @lid)
        // ==========================================================
        try {
            const chat = await client.getChatById(destino);
            if (chat && typeof chat.sendMessage === 'function') {
                if (estado.imagenGuardada) {
                    const archivo = path.join(__dirname, "..", "uploads", estado.imagenGuardada);
                    if (fs.existsSync(archivo)) {
                        const media = MessageMedia.fromFilePath(archivo);
                        await chat.sendMessage(media, { caption: texto, linkPreview: false });
                    } else {
                        await chat.sendMessage(texto, opcionesEnvio);
                    }
                } else {
                    await chat.sendMessage(texto, opcionesEnvio);
                }
                enviadoConExito = true;
            }
        } catch (chatErr) {
            console.warn(`⚠️ Fallo al obtener/usar objeto Chat: ${chatErr.message}`);
        }

        // ==========================================================
        // INTENTO B: Fallback a client.sendMessage si el Intento A falló
        // ==========================================================
        if (!enviadoConExito) {
            try {
                // Pequeña pausa estratégica: ayuda a WhatsApp Web a resolver el contexto del chat
                await new Promise(r => setTimeout(r, 1500));

                if (estado.imagenGuardada) {
                    const archivo = path.join(__dirname, "..", "uploads", estado.imagenGuardada);
                    if (fs.existsSync(archivo)) {
                        const media = MessageMedia.fromFilePath(archivo);
                        await client.sendMessage(destino, media, { caption: texto, linkPreview: false });
                    } else {
                        await client.sendMessage(destino, texto, opcionesEnvio);
                    }
                } else {
                    await client.sendMessage(destino, texto, opcionesEnvio);
                }
                enviadoConExito = true;
            } catch (sendErr) {
                // Aquí es donde atrapa el famoso error de memoize de la librería
                if (sendErr.message && sendErr.message.includes("memoize")) {
                    console.log(`⚠️ [BUG LIBRERÍA] Error de memoize en ${destino}. WhatsApp Web no pudo procesar este ID temporalmente.`);
                    // No lanzamos el error, lo manejamos como fallo de librería más abajo
                } else {
                    throw sendErr; // Si es otro error, lo lanzamos para que lo capture el catch principal
                }
            }
        }

        // 3. Evaluar resultado
        if (enviadoConExito) {
            return marcarExito(instanceId, estado, contacto, destino);
        } else {
            // Si llegamos aquí, fue por el error de memoize en el Intento B
            return marcarError(instanceId, estado, contacto, "Fallo de librería (ID @lid no soportado temporalmente)");
        }

    } catch (err) {
        console.error("❌ Error crudo en enviarMensaje:", err.message);

        // Manejo específico del bug de memoize en el catch principal
        if (err.message && err.message.includes("memoize")) {
            return marcarError(instanceId, estado, contacto, "Fallo de librería (ID @lid no soportado temporalmente)");
        }

        if (err.message && (err.message.includes("Could not find the requested contact") || err.message.includes("not registered"))) {
            return marcarError(instanceId, estado, contacto, "El número no tiene WhatsApp");
        }

        return marcarError(instanceId, estado, contacto, err.message);
    }
}

function marcarExito(instanceId, estado, contacto, chatId) {
    contacto.estadoEnvio = "enviado";
    contacto.fechaEnvio = new Date().toISOString();
    if (chatId) contacto.chatIdEnviado = chatId;

    estado.actual++;
    estado.enviadosOk++;
    estado.enviando = true;
    estado.campanaFinalizada = false;

    antiBan.resetearErroresConsecutivos(instanceId);
    antiBan.actualizarUltimoEnvio(instanceId);
    guardarEstadoSeguro(instanceId);

    console.log(`✅ Enviado (${estado.actual}/${estado.contactosCargados.length})`);

    return {
        tipo: RESULTADO.OK,
        pausa: antiBan.getPausaAleatoria(instanceId),
        contacto
    };
}

function marcarError(instanceId, estado, contacto, motivo) {
    contacto.estadoEnvio = "fallido";
    contacto.fechaEnvio = new Date().toISOString();
    contacto.error = motivo;

    if (!Array.isArray(estado.fallidos)) estado.fallidos = [];
    estado.fallidos.push({
        nombre: contacto.nombre || contacto.NOMBRE || "",
        numero: contacto.numero || contacto.NUMERO || "",
        motivo
    });

    estado.actual++;
    if (estado.actual >= estado.contactosCargados.length) {
        estado.enviando = false;
        estado.campanaFinalizada = true;
    }

    // Si es un error técnico de memoize/librería, no aplicamos la pausa larga de anti-ban
    let pausaSiguiente = 5000; // 5 segundos para avanzar rápido
    if (!motivo.includes("memoize") && !motivo.includes("librería") && !motivo.includes("caché")) {
        antiBan.registrarErrorConsecutivo(instanceId);
        pausaSiguiente = antiBan.getPausaAleatoria(instanceId);
    } else {
        console.log("⏭️ Error técnico de librería ignorado para el contador anti-ban. Pausa breve de 5s.");
    }

    guardarEstadoSeguro(instanceId);
    console.error(`❌ ${motivo}`);

    return {
        tipo: RESULTADO.OK,
        pausa: pausaSiguiente,
        contacto
    };
}

function normalizarNumero(numero) {
    if (numero === null || numero === undefined) return "";
    return String(numero).replace(/\D/g, "").trim();
}

function obtenerNumero(contacto) {
    return normalizarNumero(contacto.numero || contacto.NUMERO || contacto.Numero || "");
}

function obtenerNombre(contacto) {
    return contacto.nombre || contacto.NOMBRE || contacto.Nombre || "";
}

function reemplazarVariables(texto, contacto, estado) {
    if (!texto) return texto;
    const nombre = obtenerNombre(contacto) || '';
    const rubro = estado?.rubro || estado?.tipoCampana || '';

    return texto
        .replace(/{NOMBRE}/gi, nombre)
        .replace(/{RUBRO}/gi, rubro)
        .replace(/{TIPO}/gi, rubro);
}

function obtenerMensajeAleatorio(mensajes) {
    const lista = (mensajes || []).filter(Boolean);
    if (lista.length === 0) return "";
    return procesarSpintax(lista[Math.floor(Math.random() * lista.length)]);
}

function marcarContacto(contacto, estado, motivo = "") {
    contacto.estadoEnvio = estado;
    contacto.fechaEnvio = new Date().toISOString();
    if (motivo) contacto.error = motivo;
}

module.exports = {
    run,
    RESULTADO,
    normalizarNumero,
    obtenerNumero,
    obtenerNombre,
    obtenerMensajeAleatorio,
    marcarContacto
};

