```javascript
//==============================================================
// ENVIAR MENSAJE (Modo Fuerza Bruta para números de planilla)
//==============================================================
async function enviarMensaje(instanceId, client, estado, contacto, numero) {
    try {
        console.log(`📤 Enviando a ${numero}...`);

        // FIX DEFINITIVO: No usar getNumberId ni getChatById.
        // Forzamos directamente el formato @c.us para evitar que la librería 
        // intente resolver el @lid y colapse por su bug interno de memoize.
        const destino = `${numero}@c.us`;

        const mensajes = (estado.mensajesGuardados || []).filter(Boolean);
        if (mensajes.length === 0) {
            return { tipo: RESULTADO.ERROR, motivo: "No hay mensajes cargados" };
        }

        const mensajeBase = antiBan.seleccionarMensaje(instanceId, mensajes);
        const texto = procesarSpintax(reemplazarVariables(mensajeBase, contacto, estado));

        // La simulación de escritura ya tiene su propio blindaje en formateo.js
        try {
            await simularEscrituraHumana(client, destino, texto);
        } catch (typingErr) {
            // Si falla la escritura, no detenemos el envío
        }

        const opcionesEnvio = { linkPreview: false };

        // Envío directo y crudo. Sin intermediarios.
        if (estado.imagenGuardada) {
            const archivo = path.join(__dirname, "..", "uploads", estado.imagenGuardada);
            if (fs.existsSync(archivo)) {
                const media = MessageMedia.fromFilePath(archivo);
                await client.sendMessage(destino, media, { caption: texto, linkPreview: false });
            } else {
                await client.sendMessage(destino, texto, opcionesEnvio);
            }
        } else {
            await client.sendMessage(destino, texto, opcionesEnvio);
        }

        return marcarExito(instanceId, estado, contacto, destino);

    } catch (err) {
        console.error("❌ Error en enviarMensaje:", err.message);

        // Si el bug de memoize de la librería nos gana, lo atrapamos para que la campaña NO se muera.
        if (err.message && err.message.includes("memoize")) {
            console.log(`⚠️ [BUG LIBRERÍA] La librería colapsó con este número de la planilla. Se salta y sigue.`);
            return marcarError(instanceId, estado, contacto, "Fallo de librería (número no guardado en agenda)");
