### Paso 2: Actualizar `services/session-manager.js`

Reemplazá **todo** el contenido por esta versión. Agregué un "fallback" en `emitToUser` que emite el evento a la sala del `instanceId` también, garantizando que el frontend lo reciba sin importar a qué sala se haya unido.

```javascript
'use strict';
/**
 * MdI MultiWA
 * services/session-manager.js
 * v2.0.7 - FIX DEFINITIVO DE SALAS DE SOCKET.IO
 */

const {
    makeWASocket,
    useMultiFileAuthState,
    DisconnectReason,
    fetchLatestBaileysVersion,
    isJidBroadcast,
    isJidStatusBroadcast
} = require('@whiskeysockets/baileys');
const { Boom } = require('@hapi/boom');
const pino = require('pino');
const fs = require('fs');
const path = require('path');

const BAILEYS_SESSIONS_DIR = path.join(__dirname, '..', 'baileys_sessions');
if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) {
    fs.mkdirSync(BAILEYS_SESSIONS_DIR, { recursive: true });
}

const instances = {}; 
const userSockets = new Map();
const activeInstances = new Map();
let io = null; 

function setIO(socketIO) {
    io = socketIO;
}

// FIX CRÍTICO: Emitir a la sala del usuario Y a la sala de la instancia como fallback
function emitToUser(userId, event, data) {
    if (!io) {
        console.log(`[DEBUG emitToUser] ERROR: io no está definido`);
        return;
    }
    const uid = String(userId);
    console.log(`[DEBUG emitToUser] Emitiendo evento '${event}' a la sala: '${uid}'`);

    // 1. Emitir a la sala del usuario
    io.to(uid).emit(event, data);

    // 2. FALLBACK: Si hay un instanceId en los datos, emitir también a esa sala
    // Esto garantiza que si el frontend se unió a la sala de la instancia, también lo reciba.
    if (data && data.instanceId) {
        console.log(`[DEBUG emitToUser] Fallback: Emitiendo también a la sala de instancia: '${data.instanceId}'`);
        io.to(data.instanceId).emit(event, data);
    }
}

function registerSocket(userId, socketId) {
    const uid = String(userId);
    if (!userSockets.has(uid)) userSockets.set(uid, new Set());
    userSockets.get(uid).add(socketId);
}

function unregisterSocket(userId, socketId) {
    const uid = String(userId);
    if (userSockets.has(uid)) {
        userSockets.get(uid).delete(socketId);
        if (userSockets.get(uid).size === 0) userSockets.delete(uid);
    }
}

function setActiveInstance(userId, instanceId) {
    activeInstances.set(String(userId), instanceId);
}

function getActiveInstance(userId) {
    return activeInstances.get(String(userId)) || null;
}

function getInstanceDir(instanceId) {
    const dir = path.join(BAILEYS_SESSIONS_DIR, instanceId);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    return dir;
}

function parsePhoneNumberFromJid(jid) {
    if (!jid) return null;
    const match = jid.match(/^(\d+):?/);
    return match ? match[1] : null;
}

function extractUserId(userIdInput) {
    if (typeof userIdInput === 'object' && userIdInput !== null) {
        const id = userIdInput.id || userIdInput._id || userIdInput.userId || userIdInput.numero || 
                   userIdInput.user?.id || userIdInput.user?._id;
        if (id) return String(id);

        for (const key in userIdInput) {
            const val = userIdInput[key];
            if ((typeof val === 'string' || typeof val === 'number') && String(val).length < 50 && !String(val).includes('@')) {
                return String(val);
            }
        }
    }
    return String(userIdInput || 'unknown');
}

async function startSession(instanceId, userIdInput) {
    const userId = extractUserId(userIdInput);

    console.log(`\n================================`);
    console.log(`CREANDO INSTANCIA BAILYS`);
    console.log(`Usuario (final): ${userId}`);
    console.log(`Instancia: ${instanceId}`);
    console.log(`================================`);

    if (instances[instanceId]) {
        console.log(`⚠️ Instancia ${instanceId} ya existe. Desconectando...`);
        await disconnectSession(instanceId);
    }

    const authDir = getInstanceDir(instanceId);
    const { state, saveCreds } = await useMultiFileAuthState(authDir);

    let version;
    try {
        version = (await fetchLatestBaileysVersion()).version;
    } catch (err) {
        version = [2, 3000, 1015901307];
    }

    const sock = makeWASocket({
        auth: state,
        version,
        logger: pino({ level: 'silent' }),
        browser: ['MdI MultiWA', 'Chrome', '120.0.0.0'],
        generateHighQualityLinkPreview: false,
        syncFullHistory: false,
        markOnlineOnConnect: false,
    });

    sock.ev.on('creds.update', saveCreds);

    instances[instanceId] = {
        sock,
        userId,
        qr: null,
        ready: false,
        phoneNumber: null,
        reconnectAttempts: 0
    };

    sock.ev.on('connection.update', async (update) => {
        const { connection, lastDisconnect, qr } = update;

        if (qr) {
            instances[instanceId].qr = qr;
            instances[instanceId].ready = false;
            console.log(`📱 QR generado para ${instanceId} (Enviando a salas: '${userId}' y '${instanceId}')`);
            emitToUser(userId, 'qr', { instanceId, qr });
        }

        if (connection === 'close') {
            const statusCode = (lastDisconnect?.error instanceof Boom)?.output?.statusCode;
            const reason = lastDisconnect?.error?.output?.payload?.message || 'Desconocido';
            console.log(`❌ Conexión cerrada para ${instanceId}. Motivo: ${reason} (código: ${statusCode})`);

            if (statusCode === DisconnectReason.loggedOut || statusCode === 401) {
                console.log(`🗑️ Sesión ${instanceId} cerrada por logout. Borrando credenciales.`);
                try { fs.rmSync(authDir, { recursive: true, force: true }); } catch (e) {}
                instances[instanceId].ready = false;
                instances[instanceId].qr = null;
                emitToUser(userId, 'disconnected', { instanceId, reason: 'logged_out' });
                delete instances[instanceId];
                return;
            }

            instances[instanceId].ready = false;
            instances[instanceId].reconnectAttempts = (instances[instanceId].reconnectAttempts || 0) + 1;

            const shouldReconnect = ![DisconnectReason.loggedOut, DisconnectReason.forbidden, DisconnectReason.unavailableService].includes(statusCode);

            if (shouldReconnect && instances[instanceId].reconnectAttempts < 10) {
                const delay = Math.min(5000 * instances[instanceId].reconnectAttempts, 60000);
                console.log(`🔄 Reconectando ${instanceId} en ${delay}ms...`);
                emitToUser(userId, 'disconnected', { instanceId, reason: 'reconnecting', delay });
                setTimeout(() => { if (instances[instanceId]) startSession(instanceId, userId); }, delay);
            } else {
                console.log(`🛑 No se reconectará ${instanceId}`);
                emitToUser(userId, 'disconnected', { instanceId, reason: 'fatal' });
            }
        }

        if (connection === 'open') {
            const phoneNumber = parsePhoneNumberFromJid(sock.user?.id);
            instances[instanceId].ready = true;
            instances[instanceId].qr = null;
            instances[instanceId].phoneNumber = phoneNumber;
            instances[instanceId].reconnectAttempts = 0;

            console.log(`\n✅ WHATSAPP READY (Baileys)`);
            console.log(`Instancia: ${instanceId}`);
            console.log(`Número: ${phoneNumber}`);
            console.log(`================================\n`);

            emitToUser(userId, 'ready', { instanceId, phoneNumber });
        }
    });

    sock.ev.on('messages.upsert', async ({ messages, type }) => {
        if (type !== 'notify') return;
        for (const msg of messages) {
            if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid)) continue;
            if (msg.key.fromMe) continue;
            if (!msg.message) continue;

            const from = msg.key.remoteJid;
            const text = msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.message?.imageMessage?.caption || '';
            console.log(`💬 Mensaje recibido de ${from}: "${text.substring(0, 50)}"`);
            emitToUser(userId, 'message_received', { instanceId, from, text, timestamp: msg.messageTimestamp });
        }
    });

    return sock;
}

async function disconnectSession(instanceId) {
    const inst = instances[instanceId];
    if (!inst) return;
    console.log(`🔧 Desconectando ${instanceId}...`);
    try {
        if (inst.sock && typeof inst.sock.logout === 'function') await inst.sock.logout();
        else if (inst.sock && typeof inst.sock.end === 'function') await inst.sock.end(new Error('Manual disconnect'));
    } catch (err) {
        console.log(`⚠️ Error al cerrar socket ${instanceId}: ${err.message}`);
    }
    delete instances[instanceId];
    console.log(`✅ Desconexión completada: ${instanceId}`);
}

async function disconnectAll() {
    console.log(`🔧 Desconectando todas las instancias...`);
    for (const id of Object.keys(instances)) {
        try { await disconnectSession(id); } catch (err) { console.error(`❌ Error desconectando ${id}: ${err.message}`); }
    }
    console.log(`✅ Todas las instancias desconectadas`);
}

function getClient(instanceId) { return instances[instanceId]?.sock || null; }
function isInstanceReady(instanceId) { return instances[instanceId]?.ready === true; }
function getInstancePhone(instanceId) { return instances[instanceId]?.phoneNumber || null; }

function getAllInstances() {
    return Object.keys(instances).map(id => ({
        instanceId: id,
        userId: instances[id].userId,
        ready: instances[id].ready,
        phoneNumber: instances[id].phoneNumber,
        hasQr: !!instances[id].qr
    }));
}

function getUserInstances(userId) {
    const uid = String(userId);
    return Object.keys(instances).filter(id => instances[id].userId === uid).map(id => ({
        instanceId: id,
        userId: instances[id].userId,
        ready: instances[id].ready,
        phoneNumber: instances[id].phoneNumber,
        hasQr: !!instances[id].qr
    }));
}

function getUserInstancesResumen(userId) {
    const uid = String(userId);
    return Object.keys(instances).filter(id => instances[id].userId === uid).map(id => ({
        instanceId: id,
        ready: instances[id].ready,
        phoneNumber: instances[id].phoneNumber,
        hasQr: !!instances[id].qr
    }));
}

function getActiveInstanceId(userId) { return getActiveInstance(userId); }

function getEstado(instanceId) {
    const inst = instances[instanceId];
    if (!inst) return { ready: false, hasQr: false, phoneNumber: null, instanceId };
    return { ready: inst.ready, hasQr: !!inst.qr, phoneNumber: inst.phoneNumber, instanceId, userId: inst.userId };
}

function getPendingQr(instanceId) { return instances[instanceId]?.qr || null; }

async function restoreAllSessions() {
    console.log(`\n🔄 Restaurando sesiones Baileys...`);
    if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) { console.log('📂 No hay carpeta de sesiones Baileys aún.'); return; }
    const folders = fs.readdirSync(BAILEYS_SESSIONS_DIR).filter(f => fs.statSync(path.join(BAILEYS_SESSIONS_DIR, f)).isDirectory());
    if (folders.length === 0) { console.log('📂 No hay sesiones guardadas.'); return; }
    console.log(`📂 Sesiones encontradas: ${folders.join(', ')}`);
    for (const folder of folders) {
        const instanceId = folder;
        const authDir = path.join(BAILEYS_SESSIONS_DIR, folder);
        const hasCreds = fs.readdirSync(authDir).some(f => f.includes('creds') || f.includes('session') || f.includes('app-state'));
        if (!hasCreds) { console.log(`⚠️ ${instanceId}: carpeta vacía, saltando`); continue; }
        try {
            const userIdMatch = instanceId.match(/inst_(\d+)_/);
            const userId = userIdMatch ? userIdMatch[1] : 'unknown';
            console.log(`🔄 Restaurando ${instanceId} (userId: ${userId})...`);
            await startSession(instanceId, userId);
        } catch (err) { console.error(`❌ Error restaurando ${instanceId}: ${err.message}`); }
    }
}

module.exports = {
    setIO, startSession, disconnectSession, disconnectAll, getClient, isInstanceReady,
    getInstancePhone, getAllInstances, getUserInstances, getUserInstancesResumen,
    getActiveInstanceId, getActiveInstance, setActiveInstance, getEstado, getPendingQr,
    restoreAllSessions, registerSocket, unregisterSocket
};
