### 1. Archivo: `sockets/conversations.js`
Reemplazá **todo** el contenido por este. El cambio clave es que `salaDe` ahora devuelve el ID directo, y el evento `request_qr` ahora sí busca y envía el QR pendiente.

```javascript
/**
=============================================================
MdI MultiWA — sockets/conversations.js
Versión : v1.39.0 (Compatibilidad Baileys)
=============================================================
*/
'use strict';
const sessionManager = require('../services/session-manager');

// FIX: Devolver el ID directo sin prefijo 'user_', para que coincida 
// con cómo session-manager.js emite los eventos (io.to(userId))
function salaDe(userId) {
    return String(userId);
}

function setupSockets(io) {
    io.on('connection', (socket) => {
        console.log(`🔌 Socket conectado: ${socket.id}`);

        // ── Usuario se une a su sala ──
        socket.on('join', (userId) => {
            if (!userId) return;
            socket.userId = String(userId);

            const roomName = salaDe(userId);
            socket.join(roomName);
            console.log(`👤 [${userId.slice(-6)}] → socket ${socket.id} (Sala: ${roomName})`);

            // Si el userId parece un instanceId (ej: el frontend pasó activeId), 
            // también nos unimos a esa sala específica como blindaje extra
            if (String(userId).startsWith('inst_')) {
                socket.join(String(userId));
            }

            sessionManager.registerSocket(userId, socket.id);

            // Enviar estado actual de instancias al conectar
            const instancias = sessionManager.getUserInstancesResumen(userId);
            socket.emit('instances_update', { instancias });
            socket.emit('qr_waiting', { message: 'Esperando QR del servidor...' });
        });

        // ── Solicitud manual de QR (FIX: Ahora sí busca y envía el QR) ──
        socket.on('request_qr', (instanceId) => {
            const uid = socket.userId;
            if (!uid || !instanceId) return;

            console.log(`📤 QR manual solicitado para instancia: ${instanceId}`);
            const qr = sessionManager.getPendingQr(instanceId);

            if (qr) {
                console.log(`✅ Enviando QR pendiente a ${socket.id}`);
                socket.emit('qr', { instanceId, qr });
            } else {
                socket.emit('qr_waiting', {
                    message: 'El QR se generará automáticamente. Si no aparece, reintentá en unos segundos.'
                });
            }
        });

        // ── Reconexión — reenviar estado sin recargar la página ──
        socket.on('reconnect_state', (userId) => {
            const uid = userId || socket.userId;
            if (!uid) return;
            const instancias = sessionManager.getUserInstancesResumen(uid);
            socket.emit('instances_update', { instancias });
            console.log(`🔄 Estado reenviado a ${uid} por reconexión`);
        });

        // ── Desconexión ──
        socket.on('disconnect', (reason) => {
            console.log(`🔌 Socket desconectado: ${socket.id} — ${reason}`);
            if (socket.userId) {
                sessionManager.unregisterSocket(socket.userId, socket.id);
            }
        });

        // ── Error ──
        socket.on('error', (err) => {
            console.error(`❌ Error socket ${socket.id}:`, err);
        });
    });
}

module.exports = { setupSockets, salaDe };
```

