        console.log('🔌 Emitido join para userId:', userId);

        if (activeId && activeId !== 'undefined' && activeId !== '') {
            socket.emit('join', activeId);
            console.log('🔌 Emitido join para activeId:', activeId);
            console.log('🔌 Solicitando QR pendiente para instancia:', activeId);
            socket.emit('request_qr', activeId);
        }
    });

    socket.on('disconnect', () => {
        statusMsg.textContent = '❌ Sin conexión al servidor. Recargá la página.';
    });

    // ── Recibir QR ──
    socket.on('qr', (data) => {
        console.log('📷 EVENTO QR RECIBIDO EN FRONTEND:', data);

        if (!data || !data.qr) {
            console.warn('⚠️ El evento qr no trae data.qr');
            return;
        }

        // ✅ FIX DEFINITIVO: Baileys envía el QR como texto plano.
        // Usamos una API pública gratuita para convertir ese texto en una imagen QR real al instante.
        if (!data.qr.startsWith('data:image') && !data.qr.startsWith('http')) {
            console.log('🔄 Convirtiendo texto QR a imagen mediante API...');
            qrImg.src = 'https://api.qrserver.com/v1/create-qr-code/?size=260x260&data=' + encodeURIComponent(data.qr);
        } else {
            qrImg.src = data.qr;
        }

        qrImg.style.display = 'block';
        estadoEsp.style.display = 'none';
        qrWrapper.style.minHeight = 'auto';
        statusMsg.textContent = '📷 Escaneá el QR con WhatsApp en tu celular';
    });

    socket.on('qr_waiting', (data) => {
        statusMsg.textContent = data.message || 'Generando QR...';
    });

