#### Paso 2: LIMPIAR LA CACHÉ DEL NAVEGADOR (OBLIGATORIO)

El navegador **no va a mostrar el QR** hasta que descargue este nuevo archivo. Hacé esto en orden:

1. **Detené el servidor** con `Ctrl + C` y volvé a iniciarlo: `node index.js`
2. Abrí tu navegador en `http://localhost:3000/qr`
3. **Presioná `Ctrl + Shift + Supr`** (o `Ctrl + Shift + Delete`).
4. Seleccioná **"Imágenes y archivos en caché"** (desmarcá el resto si querés) y elegí el rango de tiempo **"Desde siempre"**.
5. Hacé clic en **"Borrar datos"**.
6. **Alternativa más rápida:** Abrí una **Ventana de Incógnito** (`Ctrl + Shift + N`) y entrá a `http://localhost:3000/qr`. Las ventanas de incógnito no usan caché.

#### Paso 3: Verificar la consola del navegador (F12)

1. En la página `/qr`, presioná `F12` para abrir las herramientas de desarrollador.
2. Andá a la pestaña **"Console"** (Consola).
3. Deberías ver estos mensajes en color blanco/azul:
   ```text
   🔧 [FRONTEND] Iniciando. userId = 1788780543868 | activeId = inst_...
   🔌 [FRONTEND] Conectado al socket
   🔌 [FRONTEND] Solicitando QR pendiente para: inst_...
   📷 [FRONTEND] ¡EVENTO QR RECIBIDO! { instanceId: '...', qr: '...' }
   🔄 [FRONTEND] Convirtiendo texto QR a imagen...
   ```

**Si ves el mensaje `📷 [FRONTEND] ¡EVENTO QR RECIBIDO!`, el QR aparecerá en la pantalla inmediatamente.** 

Si no ves ese mensaje en la consola del navegador, significa que el navegador sigue cargando el archivo viejo. En ese caso, la **Ventana de Incógnito** es la solución infalible.

¡Probalo en incógnito y contame si por fin aparece el QR! 🎯

El error ocurre porque el archivo `views/index.ejs` está intentando leer `inst.id`, pero la nueva versión de Baileys en `session-manager.js` devuelve la propiedad como `inst.instanceId`. 

Para solucionar esto **sin que tengas que editar manualmente los archivos `.ejs`**, vamos a hacer un "mapeo" inteligente en `routes/views.js`. Esto creará un alias (`id` y `listo`) para que tu interfaz siga funcionando perfectamente sin cambios.

Reemplazá **todo** el contenido de `routes/views.js` por esta versión corregida y 100% compatible con Baileys:

```javascript
const express = require('express');
const router = express.Router();
const sessionManager = require('../services/session-manager');
const { cargarEstado } = require('../state/estado');
const { isAuthenticated } = require('./auth');

router.use(isAuthenticated);

// Función auxiliar para mapear las propiedades de Baileys a los nombres que espera el EJS
function mapearInstanciasParaEJS(instanciasRaw) {
    return instanciasRaw.map(inst => ({
        ...inst,
        id: inst.instanceId,      // Alias para compatibilidad con EJS (inst.id)
        listo: inst.ready         // Alias para compatibilidad con EJS (inst.listo)
    }));
}

// ─────────────────────────────────────────────
//  GET / — Panel principal
// ─────────────────────────────────────────────
router.get('/', async (req, res) => {
    try {
        const userId = req.session.userId;
        const io = req.app.get('io');

        // FIX: Mapear para mantener compatibilidad con el EJS
        const instanciasRaw = sessionManager.getUserInstances(userId);
        const instancias = mapearInstanciasParaEJS(instanciasRaw);

        let activeId = sessionManager.getActiveInstanceId(userId);

        if (!activeId && instancias.length > 0) {
            const conectada = instancias.find(i => i.listo) || instancias[0];
            sessionManager.setActiveInstance(userId, conectada.id);
            activeId = conectada.id;
        }

        let estado = activeId ? sessionManager.getEstado(activeId) : null;

        if ((!estado || !estado.phoneNumber) && activeId) {
            const estadoDisco = cargarEstado(activeId);
            if (estadoDisco) {
                estado = { ...estado, ...estadoDisco };
            }
        }

        res.render('index', {
            estado: estado || null,
            instancias,
            activeId: activeId || null,
            sinInstancias: instancias.length === 0,
            userId: userId
        });
    } catch (error) {
        console.error('Error en GET /:', error);
        res.status(500).send('Error interno del servidor');
    }
});

// ─────────────────────────────────────────────
//  GET /qr
// ─────────────────────────────────────────────
router.get('/qr', (req, res) => {
    try {
        const userId = req.session.userId;
        const activeId = sessionManager.getActiveInstanceId(userId);
        const instanciasRaw = sessionManager.getUserInstances(userId);
        const instancias = mapearInstanciasParaEJS(instanciasRaw);

        const hayPendiente = instancias.some(i => !i.listo);
        const activaConectada = instancias.find(i => i.id === activeId && i.listo);

        if (activaConectada && !hayPendiente) {
            return res.redirect('/');
        }

        res.render('qr', {
            listo: false,
            userId: userId,
            activeId: activeId
        });
