router.get('/monitor', async (req, res) => {
    try {
        const userId = req.session.userId;
        const instanciasRaw = sessionManager.getUserInstances(userId);
        const instancias = mapearInstanciasParaEJS(instanciasRaw);

        const idsPropios = new Set(instancias.map(i => i.id));
        const activeId = (req.query.instanceId && idsPropios.has(req.query.instanceId))
            ? req.query.instanceId
            : sessionManager.getActiveInstanceId(userId);

        let estado = activeId ? sessionManager.getEstado(activeId) : null;

        if (!estado && activeId) {
            estado = cargarEstado(activeId);
        }

        res.render('monitor', {
            estado: estado || null,
            instancias,
            activeId: activeId || null
        });
    } catch (error) {
        console.error('Error en GET /monitor:', error);
        res.status(500).send('Error interno del servidor');
    }
});

