const RESULTADO = { OK: "OK", PAUSA: "PAUSA", BAJA: "BAJA", FINALIZADA: "FINALIZADA", ERROR: "ERROR" };

async function run(instanceId) {
    try {
        const estado = getEstadoInstancia(instanceId);
