    // Guardar en el servidor
    fetch('/api/monitor/guardar-conversacion', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
    }).catch(err => console.error('Error guardando conversación:', err));
});
```

