        const { conversacionId, numero } = req.body;
        const userId = req.session.userId;

        // Buscar en todas las instancias del usuario
        const instancias = sessionManager.getUserInstances(userId);
        let eliminado = false;

        for (const inst of instancias) {
            const estado = getEstadoInstancia(inst.instanceId);
            if (estado && Array.isArray(estado.conversaciones)) {
                const longitudAntes = estado.conversaciones.length;
                estado.conversaciones = estado.conversaciones.filter(c => c.id !== conversacionId);

                if (estado.conversaciones.length < longitudAntes) {
                    guardarEstadoSeguro(inst.instanceId);
                    eliminado = true;
                    break; // Ya se eliminó, no seguir buscando
                }
            }
        }

        if (eliminado) {
            return res.json({ success: true });
        } else {
            return res.status(404).json({ success: false, error: 'Conversación no encontrada' });
        }
    } catch (err) {
        console.error('Error eliminando conversación:', err);
        return res.status(500).json({ success: false, error: err.message });
    }
});

module.exports = router;
