async function startSession(instanceId, userIdInput) {
const userId = extractUserId(userIdInput);
console.log(`\n================================`);
console.log(`CREANDO INSTANCIA BAILYS`);
console.log(`Usuario (final): ${userId}`);
console.log(`Instancia: ${instanceId}`);
console.log(`================================`);

if (instances[instanceId]) {
console.log(`⚠️ Instancia ${instanceId} ya existe. Desconectando...`);
await disconnectSession(instanceId);
}

const authDir = getInstanceDir(instanceId);
const { state, saveCreds } = await useMultiFileAuthState(authDir);
let version;
try {
version = (await fetchLatestBaileysVersion()).version;
} catch (err) {
version = [2, 3000, 1015901307];
}

const sock = makeWASocket({
auth: state,
version,
logger: pino({ level: 'silent' }),
browser: ['MdI MultiWA', 'Chrome', '120.0.0.0'],
generateHighQualityLinkPreview: false,
syncFullHistory: false,
markOnlineOnConnect: false,
});

sock.ev.on('creds.update', saveCreds);
instances[instanceId] = {
sock,
userId,
qr: null,
ready: false,
phoneNumber: null,
reconnectAttempts: 0
};

sock.ev.on('connection.update', async (update) => {
const { connection, lastDisconnect, qr } = update;
// ✅ FIX CRÍTICO: Si la instancia ya fue borrada, ignorar eventos
if (!instances[instanceId]) return;

if (qr) {
instances[instanceId].qr = qr;
instances[instanceId].ready = false;
console.log(`📱 QR generado para ${instanceId} (Enviando a salas: '${userId}', '543868' y '${instanceId}')`);
emitToUser(userId, 'qr', { instanceId, qr });
}

if (connection === 'close') {
const statusCode = (lastDisconnect?.error instanceof Boom)?.output?.statusCode;
const reason = lastDisconnect?.error?.output?.payload?.message || 'Desconocido';
console.log(`❌ Conexión cerrada para ${instanceId}. Motivo: ${reason} (código: ${statusCode})`);

if (statusCode === DisconnectReason.loggedOut || statusCode === 401) {
console.log(`🗑️ Sesión ${instanceId} cerrada por logout. Borrando credenciales.`);
try { fs.rmSync(authDir, { recursive: true, force: true }); } catch (e) {}
instances[instanceId].ready = false;
instances[instanceId].qr = null;
emitToUser(userId, 'disconnected', { instanceId, reason: 'logged_out' });
delete instances[instanceId];
return;
}

instances[instanceId].ready = false;
instances[instanceId].reconnectAttempts = (instances[instanceId].reconnectAttempts || 0) + 1;
const shouldReconnect = ![DisconnectReason.loggedOut, DisconnectReason.forbidden, DisconnectReason.unavailableService].includes(statusCode);

if (shouldReconnect && instances[instanceId].reconnectAttempts < 10) {
const delay = Math.min(5000 * instances[instanceId].reconnectAttempts, 60000);
console.log(`🔄 Reconectando ${instanceId} en ${delay}ms...`);
emitToUser(userId, 'disconnected', { instanceId, reason: 'reconnecting', delay });
setTimeout(() => { if (instances[instanceId]) startSession(instanceId, userId); }, delay);
} else {
console.log(`🛑 No se reconectará ${instanceId}`);
emitToUser(userId, 'disconnected', { instanceId, reason: 'fatal' });
}
}

if (connection === 'open') {
const phoneNumber = parsePhoneNumberFromJid(sock.user?.id);
instances[instanceId].ready = true;
instances[instanceId].qr = null;
instances[instanceId].phoneNumber = phoneNumber;
instances[instanceId].reconnectAttempts = 0;
console.log(`\n✅ WHATSAPP READY (Baileys)`);
console.log(`Instancia: ${instanceId}`);
console.log(`Número: ${phoneNumber}`);
console.log(`================================\n`);
emitToUser(userId, 'ready', { instanceId, phoneNumber });
}
});

// ✅ NUEVO: Detección de INFO + Notificación al usuario + Guardar conversación
sock.ev.on('messages.upsert', async ({ messages, type }) => {
if (type !== 'notify') return;
for (const msg of messages) {
if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid) || msg.key.fromMe || !msg.message) continue;

const from = msg.key.remoteJid;
const text = msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.message?.imageMessage?.caption || '';
const textoLimpio = text.toLowerCase().trim();

console.log(`💬 Mensaje recibido de ${from}: "${text.substring(0, 50)}"`);
emitToUser(userId, 'message_received', { instanceId, from, text, timestamp: msg.messageTimestamp });

// ✅ DETECTAR RESPUESTA "INFO" Y NOTIFICAR AL USUARIO
const esInfo = textoLimpio === 'info' ||
textoLimpio === 'info!' ||
textoLimpio.includes('quiero info') ||
textoLimpio.includes('más info') ||
textoLimpio.includes('mas info') ||
textoLimpio.includes('información') ||
textoLimpio.includes('informacion');

if (esInfo) {
console.log(`🔔 Detectada respuesta INFO de ${from}`);

// Enviar notificación al celular del usuario registrado
try {
const numeroUsuario = instances[instanceId]?.phoneNumber;
if (numeroUsuario) {
const jidUsuario = `${numeroUsuario}@s.whatsapp.net`;
const numeroContacto = from.split('@')[0];

// Buscar nombre del contacto en la planilla
const estado = getEstadoInstancia(instanceId);
const contacto = estado?.contactosCargados?.find(c =>
(c.numero && c.numero.includes(numeroContacto)) ||
(c.NUMERO && c.NUMERO.includes(numeroContacto))
);
const nombreContacto = contacto ? (contacto.nombre || contacto.NOMBRE) : numeroContacto;
const rubro = estado?.rubro || estado?.tipoCampana || 'campaña';

const mensajeNotif = `🔔 *NUEVA RESPUESTA INFO*\n\n` +
`👤 *Contacto:* ${nombreContacto}\n` +
`📞 *Número:* +${numeroContacto}\n` +
`🏷️ *Rubro:* ${rubro}\n` +
`💬 *Mensaje:* "${text}"\n\n` +
`⏰ ${new Date().toLocaleString('es-AR')}`;

await sock.sendMessage(jidUsuario, { text: mensajeNotif });
console.log(`✅ Notificación enviada al usuario ${numeroUsuario}`);
} else {
console.warn(`⚠️ No se pudo notificar: número de usuario no disponible`);
}
} catch (err) {
console.error('❌ Error enviando notificación INFO:', err.message);
}
}

// Guardar conversación en el estado
try {
const estado = getEstadoInstancia(instanceId);
if (estado) {
if (!Array.isArray(estado.conversaciones)) estado.conversaciones = [];

const numeroLimpio = from.split('@')[0];
const contacto = (estado.contactosCargados || []).find(c =>
(c.numero && c.numero.includes(numeroLimpio)) || (c.NUMERO && c.NUMERO.includes(numeroLimpio))
);
const nombre = contacto ? (contacto.nombre || contacto.NOMBRE) : numeroLimpio;
const fechaStr = new Date(msg.messageTimestamp * 1000).toISOString();

let conv = estado.conversaciones.find(c => c.numero === numeroLimpio);
const nuevaConv = {
id: conv ? conv.id : `conv_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
numero: numeroLimpio,
nombre: nombre,
mensaje: text,
fecha: fechaStr,
estado: 'respondido',
origenNumero: getInstancePhone(instanceId) || 'desconocido',
rubro: estado.rubro || estado.tipoCampana || '',
imagenCampana: estado.imagenGuardada || null,
esInfo: esInfo
};

if (conv) {
Object.assign(conv, nuevaConv);
} else {
estado.conversaciones.push(nuevaConv);
}

guardarEstadoSeguro(instanceId);
emitToUser(userId, 'nueva_respuesta', nuevaConv);
}
} catch (err) {
console.error('❌ Error guardando conversación:', err.message);
}
}
});

return sock;
}

async function disconnectSession(instanceId) {
const inst = instances[instanceId];
if (!inst) return;
console.log(`🔧 Desconectando ${instanceId}...`);
try {
if (inst.sock && typeof inst.sock.logout === 'function') await inst.sock.logout();
else if (inst.sock && typeof inst.sock.end === 'function') await inst.sock.end(new Error('Manual disconnect'));
} catch (err) { console.log(`⚠️ Error al cerrar socket ${instanceId}: ${err.message}`); }
delete instances[instanceId];
console.log(`✅ Desconexión completada: ${instanceId}`);
}

async function disconnectAll() {
for (const id of Object.keys(instances)) { try { await disconnectSession(id); } catch (err) {} }
}

function getClient(instanceId) { return instances[instanceId]?.sock || null; }
function isInstanceReady(instanceId) { return instances[instanceId]?.ready === true; }
function getInstancePhone(instanceId) { return instances[instanceId]?.phoneNumber || null; }
function getAllInstances() { return Object.keys(instances).map(id => ({ instanceId: id, userId: instances[id].userId, ready: instances[id].ready, phoneNumber: instances[id].phoneNumber, hasQr: !!instances[id].qr })); }
function getUserInstances(userId) { const uid = String(userId); return Object.keys(instances).filter(id => instances[id].userId === uid).map(id => ({ instanceId: id, userId: instances[id].userId, ready: instances[id].ready, phoneNumber: instances[id].phoneNumber, hasQr: !!instances[id].qr })); }
function getUserInstancesResumen(userId) { const uid = String(userId); return Object.keys(instances).filter(id => instances[id].userId === uid).map(id => ({ instanceId: id, ready: instances[id].ready, phoneNumber: instances[id].phoneNumber, hasQr: !!instances[id].qr })); }
function getActiveInstanceId(userId) { return getActiveInstance(userId); }
function getEstado(instanceId) { const inst = instances[instanceId]; if (!inst) return { ready: false, hasQr: false, phoneNumber: null, instanceId }; return { ready: inst.ready, hasQr: !!inst.qr, phoneNumber: inst.phoneNumber, instanceId, userId: inst.userId }; }
function getPendingQr(instanceId) { return instances[instanceId]?.qr || null; }

async function restoreAllSessions() {
if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) return;
const folders = fs.readdirSync(BAILEYS_SESSIONS_DIR).filter(f => fs.statSync(path.join(BAILEYS_SESSIONS_DIR, f)).isDirectory());
for (const folder of folders) {
