if (!hasCreds) continue;
try {
const userIdMatch = instanceId.match(/inst_(\d+)_/);
await startSession(instanceId, userIdMatch ? userIdMatch[1] : 'unknown');
} catch (err) { console.error(`❌ Error restaurando ${instanceId}:`, err.message); }
}
}

