    });

    sock.ev.on('messages.upsert', async ({ messages, type }) => {
        if (type !== 'notify') return;
        for (const msg of messages) {
            if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid) || msg.key.fromMe || !msg.message) continue;

            const from = msg.key.remoteJid;
            const text = msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.message?.imageMessage?.caption || '';
            const textoLimpio = text.toLowerCase().trim();

            console.log(`💬 Mensaje de ${from}: "${text.substring(0, 50)}"`);
            emitToUser(userId, 'message_received', { instanceId, from, text, timestamp: msg.messageTimestamp });

            const esInfo = textoLimpio === 'info' || textoLimpio === 'info!' || 
                          textoLimpio.includes('quiero info') || textoLimpio.includes('más info') ||
                          textoLimpio.includes('información') || textoLimpio.includes('informacion');

            if (esInfo) {
                console.log(`🔔 Detectado INFO de ${from}`);
                try {
                    const estado = getEstadoInstancia(instanceId);
                    const numeroJid = from.split('@')[0];

                    let contacto = null;
                    let numeroReal = numeroJid;
                    let nombreContacto = 'Desconocido';

                    if (estado && Array.isArray(estado.contactosCargados)) {
                        const numJidNorm = normalizarNumero(numeroJid);
                        contacto = estado.contactosCargados.find(c => {
                            const numPlanilla = normalizarNumero(c.numero || c.NUMERO);
                            return numPlanilla === numJidNorm || numPlanilla.includes(numJidNorm) || numJidNorm.includes(numPlanilla);
                        });
                    }

                    if (contacto) {
                        nombreContacto = contacto.nombre || contacto.NOMBRE || 'Desconocido';
                        numeroReal = contacto.numero || contacto.NUMERO || numeroJid;
                        console.log(`✅ Contacto: ${nombreContacto} (${numeroReal})`);
                    }

                    const tipoCampana = estado?.tipoCampana || '';
                    const rubro = estado?.rubro || tipoCampana || 'campaña';

                    let respuestaAuto = '';
                    if (estado?.respuestasInfoPorTipo && tipoCampana && estado.respuestasInfoPorTipo[tipoCampana]) {
                        respuestaAuto = estado.respuestasInfoPorTipo[tipoCampana];
                    } else if (estado?.respuestaInfo) {
                        respuestaAuto = estado.respuestaInfo;
                    }

                    if (respuestaAuto) {
                        const respuestaFinal = respuestaAuto
                            .replace(/\{\{\s*NOMBRE\s*\}\}/gi, nombreContacto)
                            .replace(/\{\s*NOMBRE\s*\}/gi, nombreContacto)
                            .replace(/\bNOMBRE\b/gi, nombreContacto)
                            .replace(/\{\{\s*RUBRO\s*\}\}/gi, rubro)
                            .replace(/\{\s*RUBRO\s*\}/gi, rubro)
                            .replace(/\bRUBRO\b/gi, rubro);

                        try {
