## ✅ Solución Definitiva: Resolver LIDs

Reemplazá **TODO** `services/session-manager.js` por esta versión que resuelve LIDs automáticamente:

```javascript
'use strict';
const { makeWASocket, useMultiFileAuthState, DisconnectReason, fetchLatestBaileysVersion, isJidBroadcast, isJidStatusBroadcast } = require('@whiskeysockets/baileys');
const { Boom } = require('@hapi/boom');
const pino = require('pino');
const fs = require('fs');
const path = require('path');
const { getEstadoInstancia, guardarEstadoSeguro } = require('../state/estado');

const BAILEYS_SESSIONS_DIR = path.join(__dirname, '..', 'baileys_sessions');
if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) fs.mkdirSync(BAILEYS_SESSIONS_DIR, { recursive: true });

const instances = {};
const activeInstances = new Map();
let io = null;

function setIO(socketIO) { io = socketIO; }

function emitToUser(userId, event, data) {
    if (!io) return;
    const uid = String(userId);
    io.to(uid).emit(event, data);
    if (uid === '1788780543868') io.to('543868').emit(event, data);
    if (data && data.instanceId) io.to(data.instanceId).emit(event, data);
}

function setActiveInstance(userId, instanceId) { activeInstances.set(String(userId), instanceId); }
function getActiveInstance(userId) { return activeInstances.get(String(userId)) || null; }

function getInstanceDir(instanceId) {
    const dir = path.join(BAILEYS_SESSIONS_DIR, instanceId);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    return dir;
}

function parsePhoneNumberFromJid(jid) {
    if (!jid) return null;
    const match = jid.match(/^(\d+):?/);
    return match ? match[1] : null;
}

function extractUserId(userIdInput) {
    if (typeof userIdInput === 'object' && userIdInput !== null) {
        const id = userIdInput.id || userIdInput._id || userIdInput.userId || userIdInput.numero;
        if (id) return String(id);
    }
    return String(userIdInput || 'unknown');
}

// ✅ NUEVA FUNCIÓN: Resolver LID a número de teléfono real
function resolverLid(instanceId, jid) {
    if (!jid) return null;

    // Si ya es un número normal (no LID), devolverlo directamente
    if (!jid.includes('@lid')) {
        return jid.split('@')[0];
    }

    // Es un LID, buscar en los archivos de mapeo
    const authDir = getInstanceDir(instanceId);
    const lidId = jid.split('@')[0];

    // Buscar archivo lid-mapping-XXXXX_reverse.json
    const mappingFiles = fs.readdirSync(authDir).filter(f => 
        f.startsWith('lid-mapping-') && f.includes(lidId)
    );

    if (mappingFiles.length > 0) {
        try {
            const mappingFile = path.join(authDir, mappingFiles[0]);
            const mapping = JSON.parse(fs.readFileSync(mappingFile, 'utf8'));

            // El archivo contiene el mapeo LID -> número real
            if (mapping && mapping.lid && mapping.phoneNumber) {
                console.log(`[LID RESOLVER] ✅ ${lidId} -> ${mapping.phoneNumber}`);
                return mapping.phoneNumber;
            }

            // Si no tiene estructura esperada, buscar en el contenido
            const content = JSON.stringify(mapping);
            const phoneMatch = content.match(/549\d{10}/);
            if (phoneMatch) {
                console.log(`[LID RESOLVER] ✅ ${lidId} -> ${phoneMatch[0]} (extraído)`);
                return phoneMatch[0];
            }
        } catch (err) {
            console.warn(`[LID RESOLVER] ⚠️ Error leyendo mapeo: ${err.message}`);
        }
    }

    // Fallback: buscar en TODOS los archivos lid-mapping de la instancia
    const allMappingFiles = fs.readdirSync(authDir).filter(f => 
        f.startsWith('lid-mapping-') && f.endsWith('.json')
    );

    for (const file of allMappingFiles) {
        try {
            const filePath = path.join(authDir, file);
            const content = fs.readFileSync(filePath, 'utf8');

            if (content.includes(lidId)) {
                const mapping = JSON.parse(content);
                const phoneMatch = content.match(/549\d{10}/);
                if (phoneMatch) {
                    console.log(`[LID RESOLVER] ✅ ${lidId} -> ${phoneMatch[0]} (búsqueda amplia)`);
                    return phoneMatch[0];
                }
            }
        } catch (err) {
            // Ignorar errores de lectura
        }
    }

    console.log(`[LID RESOLVER] ❌ No se pudo resolver LID: ${lidId}`);
    return lidId;
}

function normalizarNumero(num) {
    if (!num) return '';
    let n = String(num).replace(/\D/g, '');
    if (n.startsWith('549')) n = n.substring(3);
    else if (n.startsWith('54')) n = n.substring(2);
    else if (n.startsWith('0')) n = n.substring(1);
    return n;
}

async function startSession(instanceId, userIdInput) {
    const userId = extractUserId(userIdInput);
    console.log(`\n================================\nCREANDO INSTANCIA BAILYS\nUsuario: ${userId}\nInstancia: ${instanceId}\n================================`);

    if (instances[instanceId]) {
        console.log(`⚠️ Instancia ${instanceId} ya existe. Desconectando...`);
        await disconnectSession(instanceId);
    }

    const authDir = getInstanceDir(instanceId);
    const { state, saveCreds } = await useMultiFileAuthState(authDir);
    let version;
    try { version = (await fetchLatestBaileysVersion()).version; } 
    catch (err) { version = [2, 3000, 1015901307]; }

    const sock = makeWASocket({
        auth: state, version, logger: pino({ level: 'silent' }),
        browser: ['MdI MultiWA', 'Chrome', '120.0.0.0'],
        generateHighQualityLinkPreview: false, syncFullHistory: false, markOnlineOnConnect: false,
    });

    sock.ev.on('creds.update', saveCreds);
    instances[instanceId] = { sock, userId, qr: null, ready: false, phoneNumber: null, reconnectAttempts: 0 };

    sock.ev.on('connection.update', async (update) => {
        const { connection, lastDisconnect, qr } = update;
        if (!instances[instanceId]) return;

        if (qr) {
            instances[instanceId].qr = qr;
            instances[instanceId].ready = false;
            emitToUser(userId, 'qr', { instanceId, qr });
        }

        if (connection === 'close') {
            const statusCode = (lastDisconnect?.error instanceof Boom)?.output?.statusCode;
            const reason = lastDisconnect?.error?.output?.payload?.message || 'Desconocido';
            console.log(`❌ Conexión cerrada: ${reason} (${statusCode})`);

            if (statusCode === DisconnectReason.loggedOut || statusCode === 401) {
                try { fs.rmSync(authDir, { recursive: true, force: true }); } catch (e) {}
                instances[instanceId].ready = false;
                instances[instanceId].qr = null;
                emitToUser(userId, 'disconnected', { instanceId, reason: 'logged_out' });
                delete instances[instanceId];
                return;
            }

            instances[instanceId].ready = false;
            instances[instanceId].reconnectAttempts++;
            if (instances[instanceId].reconnectAttempts < 10) {
                const delay = Math.min(5000 * instances[instanceId].reconnectAttempts, 60000);
                setTimeout(() => { if (instances[instanceId]) startSession(instanceId, userId); }, delay);
            }
        }

        if (connection === 'open') {
            const phoneNumber = parsePhoneNumberFromJid(sock.user?.id);
            instances[instanceId].ready = true;
            instances[instanceId].qr = null;
            instances[instanceId].phoneNumber = phoneNumber;
            instances[instanceId].reconnectAttempts = 0;
            console.log(`\n✅ WHATSAPP READY\nNúmero: ${phoneNumber}\n`);
            emitToUser(userId, 'ready', { instanceId, phoneNumber });
        }
    });

    sock.ev.on('messages.upsert', async ({ messages, type }) => {
        if (type !== 'notify') return;
        for (const msg of messages) {
            if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid) || msg.key.fromMe || !msg.message) continue;

            const from = msg.key.remoteJid;
            const text = msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.message?.imageMessage?.caption || '';
            const textoLimpio = text.toLowerCase().trim();

            console.log(`💬 Mensaje de ${from}: "${text.substring(0, 50)}"`);
            emitToUser(userId, 'message_received', { instanceId, from, text, timestamp: msg.messageTimestamp });

            const esInfo = textoLimpio === 'info' || textoLimpio === 'info!' || 
                          textoLimpio.includes('quiero info') || textoLimpio.includes('más info') ||
                          textoLimpio.includes('información') || textoLimpio.includes('informacion');

            if (esInfo) {
                console.log(`🔔 Detectado INFO de ${from}`);
                try {
                    const estado = getEstadoInstancia(instanceId);

                    // ✅ RESOLVER LID A NÚMERO REAL
                    const numeroReal = resolverLid(instanceId, from);
                    console.log(`[INFO] Número resuelto: ${numeroReal}`);

                    let contacto = null;
                    let nombreContacto = 'Desconocido';

                    if (estado && Array.isArray(estado.contactosCargados) && numeroReal) {
                        const numJidNorm = normalizarNumero(numeroReal);
                        console.log(`[INFO] Buscando en planilla: ${numJidNorm}`);

                        contacto = estado.contactosCargados.find(c => {
                            const numPlanilla = normalizarNumero(c.numero || c.NUMERO);
                            return numPlanilla === numJidNorm || numPlanilla.includes(numJidNorm) || numJidNorm.includes(numPlanilla);
                        });
                    }

                    if (contacto) {
                        nombreContacto = contacto.nombre || contacto.NOMBRE || 'Desconocido';
                        console.log(`✅ Contacto encontrado: ${nombreContacto} (${numeroReal})`);
                    } else {
                        console.log(`⚠️ Contacto NO encontrado, usando número: ${numeroReal}`);
                    }

                    const tipoCampana = estado?.tipoCampana || '';
                    const rubro = estado?.rubro || tipoCampana || 'campaña';

                    let respuestaAuto = '';
                    if (estado?.respuestasInfoPorTipo && tipoCampana && estado.respuestasInfoPorTipo[tipoCampana]) {
                        respuestaAuto = estado.respuestasInfoPorTipo[tipoCampana];
                    } else if (estado?.respuestaInfo) {
                        respuestaAuto = estado.respuestaInfo;
                    }

                    if (respuestaAuto) {
                        const respuestaFinal = respuestaAuto
                            .replace(/\{\{\s*NOMBRE\s*\}\}/gi, nombreContacto)
                            .replace(/\{\s*NOMBRE\s*\}/gi, nombreContacto)
                            .replace(/\bNOMBRE\b/gi, nombreContacto)
                            .replace(/\{\{\s*RUBRO\s*\}\}/gi, rubro)
                            .replace(/\{\s*RUBRO\s*\}/gi, rubro)
                            .replace(/\bRUBRO\b/gi, rubro);

                        try {
                            await sock.sendPresenceUpdate('composing', from);
                            const tiempo = Math.min(Math.max(respuestaFinal.length * 30, 1500), 3000);
                            await new Promise(r => setTimeout(r, tiempo));
                            await sock.sendPresenceUpdate('paused', from);
                        } catch (e) { console.warn('⚠️ Error simulando escritura:', e.message); }

                        await sock.sendMessage(from, { text: respuestaFinal });
                        console.log(`✅ Respuesta enviada a ${numeroReal}`);
                    }

                    // ✅ NOTIFICACIÓN AL ADMIN
                    const numeroAdmin = '5493513043371';
                    const jidAdmin = `${numeroAdmin}@s.whatsapp.net`;

