Por:

```js
function getTiempoEscritura(mensaje) {
    const texto = String(mensaje || '');

    if (!texto) return 2000;

    const palabras = texto.split(/\s+/).length;

    // Velocidad humana: 15-35 palabras por minuto
    const wpm = 15 + Math.random() * 20;

    // Tiempo base en segundos
    let segundos = (palabras / wpm) * 60;

    // Agregar ruido aleatorio (±20%)
    segundos *= (0.8 + Math.random() * 0.4);

    // Convertir a ms y clampar
    const ms = segundos * 1000;

    // Mínimo 2s, máximo 12s
    return Math.min(Math.max(ms, 2000), 12000);
}
```

