async function removeInstance(
    userId,
    instanceId
) {
    const client =
        clients.get(instanceId);
    if (client) {
        await gracefulDestroy(client);
        clients.delete(instanceId);
    }
    const session =
        sessions.get(userId);
    if (session) {
        session.instances.delete(instanceId);
        if (
            session.activeId === instanceId
        ) {
            const restantes =
                [...session.instances.keys()];
            session.activeId =
                restantes.length
                    ? restantes[0]
                    : null;
        }
    }
    //----------------------------------------------------------
    // Limpiar archivos en disco
    //----------------------------------------------------------
    try {
        const estado =
            getEstadoInstancia(
                instanceId
            );
        if (
            estado?.imagenGuardada
        ) {
            const rutaImagen =
                path.join(
                    __dirname,
                    '..',
                    'uploads',
                    estado.imagenGuardada
                );
            if (
                fs.existsSync(rutaImagen)
            ) {
                fs.unlinkSync(
                    rutaImagen
                );
            }
        }
    }
    catch (err) {
        console.warn(
            `⚠ No se pudo borrar la imagen de campaña (${instanceId}):`,
            err.message
        );
    }
    try {
        const rutaEstado =
            path.join(
                __dirname,
                '..',
                'data',
                `estado_${instanceId}.json`
            );
        if (
            fs.existsSync(rutaEstado)
        ) {
            fs.unlinkSync(
                rutaEstado
            );
        }
    }
    catch (err) {
        console.warn(
            `⚠ No se pudo borrar estado_${instanceId}.json:`,
            err.message
        );
    }
    try {
        const rutaSesion =
            path.join(
                SESSIONS_DIR,
                `session-${instanceId}`
            );
        if (
            fs.existsSync(rutaSesion)
        ) {
            fs.rmSync(
