//==============================================================
function guardarInstanciaSesion(
    userId,
    instanceId,
    datos
){
    const session =
        sessions.get(userId);
    if(!session){
        return false;
    }
    const actual =
        session.instances.get(instanceId);
    if(!actual){
        return false;
    }
    Object.assign(
        actual,
        datos
    );
    session.instances.set(
        instanceId,
        actual
    );
    // FIX: guardarInstancia() es la función importada de
    // instancias-persistencia.
    guardarInstancia(
        userId,
        instanceId,
        actual
    );
    return true;
}

