    if (num.startsWith('0')) num = num.substring(1);
    const codigosAreaArgentina = [
        '11','220','221','223','224','225','226','227','228','229',
        '230','231','232','233','234','235','236','237','238','239',
        '260','261','262','263','264','265','266','267','280',
