            if (err.message && (err.message.includes("Could not find") || err.message.includes("not registered") || err.message.includes("invalid"))) {
                console.log(`❌ El número ${numero} no está registrado en WhatsApp.`);
                return marcarError(instanceId, estado, contacto, "Número no registrado en WhatsApp");
            }
            console.log(`⚠️ Error en getNumberId: ${err.message}. Intentando envío directo con fallback...`);
        }

        const mensajes = (estado.mensajesGuardados || []).filter(Boolean);
        if (mensajes.length === 0) {
            return { tipo: RESULTADO.ERROR, motivo: "No hay mensajes cargados" };
        }

        const mensajeBase = antiBan.seleccionarMensaje(instanceId, mensajes);
        const texto = procesarSpintax(reemplazarVariables(mensajeBase, contacto, estado));

        // CAPA 2: Intento de envío con manejo específico del bug de memoize
        try {
            await simularEscrituraHumana(client, destino, texto);

            const opcionesEnvio = { linkPreview: false };
            if (estado.imagenGuardada) {
                const archivo = path.join(__dirname, "..", "uploads", estado.imagenGuardada);
                if (fs.existsSync(archivo)) {
                    const media = MessageMedia.fromFilePath(archivo);
                    await client.sendMessage(destino, media, { caption: texto, linkPreview: false });
                } else {
                    await client.sendMessage(destino, texto, opcionesEnvio);
                }
            } else {
                await client.sendMessage(destino, texto, opcionesEnvio);
            }

            return marcarExito(instanceId, estado, contacto, destino);

        } catch (sendErr) {
            // CAPA 3: Captura específica del bug de memoize si aún así ocurre
            if (sendErr.message && sendErr.message.includes("memoize")) {
                console.log(`⚠️ [BUG LIBRERÍA] Error de memoize en ${destino}. La caché de WhatsApp Web falló.`);
                return marcarError(instanceId, estado, contacto, "Fallo de caché/librería (posible número inválido)");
            }

            if (esErrorFrameDetached(sendErr)) {
                return { tipo: RESULTADO.ERROR, motivo: `WhatsApp desconectado: ${sendErr.message}`, _frameDetached: true };
            }

            return marcarError(instanceId, estado, contacto, sendErr.message);
        }

    } catch (err) {
        console.error("❌ Error crudo no manejado en enviarMensaje:", err.message);
        return marcarError(instanceId, estado, contacto, err.message);
    }
}
