### 🔧 Paso 2: Modificar `marcarError` para evitar pausas largas por bugs

Buscá la función `marcarError` y reemplazala por esta. El cambio clave es que si el motivo menciona "librería", "memoize" o "caché", **fuerza una pausa de solo 5 segundos** en lugar de consultar al anti-ban (que fue lo que te puso la pausa de 9 minutos).

```javascript
//==============================================================
// MARCAR ERROR
//==============================================================
function marcarError(instanceId, estado, contacto, motivo) {
    contacto.estadoEnvio = "fallido";
    contacto.fechaEnvio = new Date().toISOString();
    contacto.error = motivo;

    if (!Array.isArray(estado.fallidos)) estado.fallidos = [];
    estado.fallidos.push({
        nombre: contacto.nombre || contacto.NOMBRE || "",
        numero: contacto.numero || contacto.NUMERO || "",
        motivo
    });

    estado.actual++;
    if (estado.actual >= estado.contactosCargados.length) {
        estado.enviando = false;
        estado.campanaFinalizada = true;
    }

    // Si es un error técnico de la librería, aplicamos una pausa breve (5s) 
    // para pasar al siguiente contacto sin activar las pausas largas del anti-ban.
    let pausaSiguiente = 5000; // 5 segundos por defecto para errores de librería

    if (!motivo.includes("librería") && !motivo.includes("memoize") && !motivo.includes("caché") && !motivo.includes("no registrado")) {
        antiBan.registrarErrorConsecutivo(instanceId);
        pausaSiguiente = antiBan.getPausaAleatoria(instanceId);
    } else {
        console.log("⏭️ Error técnico/librería ignorado para el contador anti-ban. Pausa breve de 5s.");
    }

    guardarEstadoSeguro(instanceId);
    console.error(`❌ ${motivo}`);

    return {
        tipo: RESULTADO.OK,
        pausa: pausaSiguiente,
        contacto
    };
}
