            } else {
                await client.sendMessage(destino, texto, opcionesEnvio);
            }

            return marcarExito(instanceId, estado, contacto, destino);

        } catch (sendErr) {
            // Atrapamos CUALQUIER error relacionado con IDs de la librería
            if (sendErr.message && (sendErr.message.includes("memoize") || sendErr.message.includes("LID") || sendErr.message.includes("undefined"))) {
                console.log(`⚠️ [BUG LIBRERÍA] WhatsApp rechazó este ID. Se salta.`);
                return marcarError(instanceId, estado, contacto, "Fallo técnico de librería (ID/LID no soportado)");
            }
            throw sendErr; // Si es otro error, lo dejamos caer al catch principal
        }

    } catch (err) {
        console.error("❌ Error en enviarMensaje:", err.message);
        return marcarError(instanceId, estado, contacto, err.message);
    }
}

function marcarExito(instanceId, estado, contacto, chatId) {
    contacto.estadoEnvio = "enviado";
    contacto.fechaEnvio = new Date().toISOString();
    if (chatId) contacto.chatIdEnviado = chatId;

    estado.actual++;
    estado.enviadosOk++;
    estado.enviando = true;
    estado.campanaFinalizada = false;

    if (antiBan.resetearErroresConsecutivos) antiBan.resetearErroresConsecutivos(instanceId);
    if (antiBan.actualizarUltimoEnvio) antiBan.actualizarUltimoEnvio(instanceId);
    guardarEstadoSeguro(instanceId);

    console.log(`✅ Enviado (${estado.actual}/${estado.contactosCargados.length})`);

    const pausa = antiBan.getPausaAleatoria ? antiBan.getPausaAleatoria(instanceId) : 5000;
    return { tipo: RESULTADO.OK, pausa: Math.max(5000, pausa), contacto };
}

function marcarError(instanceId, estado, contacto, motivo) {
    contacto.estadoEnvio = "fallido";
    contacto.fechaEnvio = new Date().toISOString();
    contacto.error = motivo;

    if (!Array.isArray(estado.fallidos)) estado.fallidos = [];
    estado.fallidos.push({ nombre: contacto.nombre || contacto.NOMBRE || "", numero: contacto.numero || contacto.NUMERO || "", motivo });

    estado.actual++;
    if (estado.actual >= estado.contactosCargados.length) {
        estado.enviando = false;
        estado.campanaFinalizada = true;
    }

    // BLINDAJE TOTAL: Si el motivo tiene alguna de estas palabras, es culpa de la librería.
    // NO registramos error consecutivo y forzamos 5 segundos.
    const esErrorLibreria = motivo && (
        motivo.includes("memoize") || 
        motivo.includes("librería") || 
        motivo.includes("LID") || 
        motivo.includes("resoluble") ||
        motivo.includes("undefined")
    );

    let pausaSiguiente = 5000;
    if (!esErrorLibreria) {
        if (antiBan.registrarErrorConsecutivo) antiBan.registrarErrorConsecutivo(instanceId);
        pausaSiguiente = antiBan.getPausaAleatoria ? antiBan.getPausaAleatoria(instanceId) : 5000;
    } else {
        console.log("⏭️ Error técnico de librería ignorado. Pausa de 5s.");
    }

    // Garantizamos que NUNCA sea menor a 5 segundos para evitar bucles infinitos
    pausaSiguiente = Math.max(5000, pausaSiguiente);

    guardarEstadoSeguro(instanceId);
    console.error(`❌ ${motivo}`);

    return { tipo: RESULTADO.OK, pausa: pausaSiguiente, contacto };
}

module.exports = { run, RESULTADO };
```

### 🚀 Pasos para aplicar (Último intento estructurado):

1. **Detené el servidor** con `Ctrl + C`.
2. Abrí `services/campaign-runner.js`, **borrá TODO** y pegá el código de arriba. Guardá.
3. **Limpiá la sesión corrupta** (esto es vital porque la sesión actual ya tiene la caché de LIDs "envenenada" por los intentos anteriores). Ejecutá en la CMD:
   ```cmd
   rmdir /s /q "C:\Users\Molino PC\Desktop\MdI multiWA\sessions"
   rmdir /s /q "C:\Users\Molino PC\Desktop\MdI multiWA\.wwebjs_auth"
   ```
4. Iniciá el servidor: `node index.js`
5. **Escaneá el QR de nuevo** con el celular de la agencia.
6. Cargá los contactos e iniciá la campaña.

### ¿Por qué esto es diferente?
1. **No forzamos nada**: Usamos el ID que WhatsApp nos da. Si nos da `@lid`, usamos `@lid`. Si nos da `@c.us`, usamos `@c.us`.
2. **Blindaje absoluto contra pausas largas**: La función `marcarError` ahora busca las palabras "memoize", "LID", "resoluble" o "undefined". Si encuentra alguna, **ignora por completo el contador de errores** y fuerza una pausa de exactamente 5 segundos.
3. **Limpieza de sesión**: Al borrar las carpetas de sesión, le damos a WhatsApp Web una caché limpia, lo que a veces resuelve mágicamente los problemas de LID que se acumulan con el tiempo.

Hacé estos 6 pasos. Si después de esto sigue fallando el 100% de los números, el problema ya no es el código, sino que la versión actual de `whatsapp-web.js` es incompatible con la última actualización de WhatsApp para números no guardados, y la única salida operativa real será agregar esos contactos a la agenda del teléfono. Probalo y contame.

¡Excelente decisión! Es el paso profesional correcto. Baileys se conecta directamente al protocolo de WhatsApp (sin usar un navegador Chrome oculto), lo que lo hace mucho más rápido, estable y, lo más importante, **maneja los IDs `@lid` de forma nativa sin colapsar**.

Vamos a hacer esto de forma **quirúrgica y segura**: no vamos a tocar tu aplicación principal todavía. Primero, vamos a crear un script de prueba independiente para confirmar que Baileys puede enviar un mensaje a esos números "problemáticos" sin errores.

