Copiá y pegá **todo** este bloque reemplazando el contenido actual:

```javascript
'use strict';
/**
 * MdI MultiWA
 * services/session-manager.js
 * v2.0.1 - Motor Baileys (@whiskeysockets/baileys)
 * FIX: Agregada getUserInstances para compatibilidad con views.js
 */

const {
    makeWASocket,
    useMultiFileAuthState,
    DisconnectReason,
    fetchLatestBaileysVersion,
    isJidBroadcast,
    isJidStatusBroadcast
} = require('@whiskeysockets/baileys');
const { Boom } = require('@hapi/boom');
const pino = require('pino');
const fs = require('fs');
const path = require('path');

// ============================================================
// CONFIGURACIÓN
// ============================================================
const BAILEYS_SESSIONS_DIR = path.join(__dirname, '..', 'baileys_sessions');

if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) {
    fs.mkdirSync(BAILEYS_SESSIONS_DIR, { recursive: true });
}

// ============================================================
// ESTADO EN MEMORIA
// ============================================================
const instances = {}; 

let io = null; 

// ============================================================
// INYECCIÓN DE SOCKET.IO
// ============================================================
function setIO(socketIO) {
    io = socketIO;
}

function emitToUser(userId, event, data) {
    if (!io) return;
    io.to(userId).emit(event, data);
}

// ============================================================
// HELPERS
// ============================================================
function getInstanceDir(instanceId) {
    const dir = path.join(BAILEYS_SESSIONS_DIR, instanceId);
    if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
    }
    return dir;
}

function parsePhoneNumberFromJid(jid) {
    if (!jid) return null;
    const match = jid.match(/^(\d+):?/);
    return match ? match[1] : null;
}

// ============================================================
// CREAR/INICIAR SESIÓN
// ============================================================
async function startSession(instanceId, userId) {
    console.log(`\n================================`);
    console.log(`CREANDO INSTANCIA BAILYS`);
    console.log(`Usuario: ${userId}`);
    console.log(`Instancia: ${instanceId}`);
    console.log(`================================`);

    if (instances[instanceId]) {
        console.log(`⚠️ Instancia ${instanceId} ya existe. Desconectando...`);
        await disconnectSession(instanceId);
    }

    const authDir = getInstanceDir(instanceId);
    const { state, saveCreds } = await useMultiFileAuthState(authDir);

    let version;
    try {
        version = (await fetchLatestBaileysVersion()).version;
    } catch (err) {
        version = [2, 3000, 1015901307];
    }

    const sock = makeWASocket({
        auth: state,
        version,
        logger: pino({ level: 'silent' }),
        browser: ['MdI MultiWA', 'Chrome', '120.0.0.0'],
        generateHighQualityLinkPreview: false,
        syncFullHistory: false,
        markOnlineOnConnect: false,
    });

    sock.ev.on('creds.update', saveCreds);

    instances[instanceId] = {
        sock,
        userId,
        qr: null,
        ready: false,
        phoneNumber: null,
        reconnectAttempts: 0
    };

    sock.ev.on('connection.update', async (update) => {
        const { connection, lastDisconnect, qr } = update;

        if (qr) {
            instances[instanceId].qr = qr;
            instances[instanceId].ready = false;
            console.log(`📱 QR generado para ${instanceId}`);
            emitToUser(userId, 'qr', { instanceId, qr });
        }

        if (connection === 'close') {
            const statusCode = (lastDisconnect?.error instanceof Boom)?.output?.statusCode;
            const reason = lastDisconnect?.error?.output?.payload?.message || 'Desconocido';

            console.log(`❌ Conexión cerrada para ${instanceId}. Motivo: ${reason} (código: ${statusCode})`);

            if (statusCode === DisconnectReason.loggedOut || statusCode === 401) {
                console.log(`🗑️ Sesión ${instanceId} cerrada por logout. Borrando credenciales.`);
                try { fs.rmSync(authDir, { recursive: true, force: true }); } catch (e) {}
                instances[instanceId].ready = false;
                instances[instanceId].qr = null;
                emitToUser(userId, 'disconnected', { instanceId, reason: 'logged_out' });
                delete instances[instanceId];
                return;
            }

            instances[instanceId].ready = false;
            instances[instanceId].reconnectAttempts = (instances[instanceId].reconnectAttempts || 0) + 1;

            const shouldReconnect = ![
                DisconnectReason.loggedOut,
                DisconnectReason.forbidden,
                DisconnectReason.unavailableService
            ].includes(statusCode);

            if (shouldReconnect && instances[instanceId].reconnectAttempts < 10) {
                const delay = Math.min(5000 * instances[instanceId].reconnectAttempts, 60000);
                console.log(`🔄 Reconectando ${instanceId} en ${delay}ms (intento ${instances[instanceId].reconnectAttempts})...`);
                emitToUser(userId, 'disconnected', { instanceId, reason: 'reconnecting', delay });

                setTimeout(() => {
                    if (instances[instanceId]) {
                        startSession(instanceId, userId);
                    }
                }, delay);
            } else {
                console.log(`🛑 No se reconectará ${instanceId} (intentos agotados o error fatal)`);
                emitToUser(userId, 'disconnected', { instanceId, reason: 'fatal' });
            }
        }

        if (connection === 'open') {
            const phoneNumber = parsePhoneNumberFromJid(sock.user?.id);
            instances[instanceId].ready = true;
            instances[instanceId].qr = null;
            instances[instanceId].phoneNumber = phoneNumber;
            instances[instanceId].reconnectAttempts = 0;

            console.log(`\n✅ WHATSAPP READY (Baileys)`);
            console.log(`Instancia: ${instanceId}`);
            console.log(`Número: ${phoneNumber}`);
            console.log(`================================\n`);

            emitToUser(userId, 'ready', { instanceId, phoneNumber });
        }
    });

    sock.ev.on('messages.upsert', async ({ messages, type }) => {
        if (type !== 'notify') return;

        for (const msg of messages) {
            if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid)) continue;
            if (msg.key.fromMe) continue;
            if (!msg.message) continue;

            const from = msg.key.remoteJid;
            const text = msg.message?.conversation || 
                         msg.message?.extendedTextMessage?.text ||
                         msg.message?.imageMessage?.caption || '';

            console.log(`💬 Mensaje recibido de ${from}: "${text.substring(0, 50)}"`);

            emitToUser(userId, 'message_received', {
                instanceId,
                from,
                text,
                timestamp: msg.messageTimestamp
            });
        }
    });

    return sock;
}

// ============================================================
// DESCONECTAR SESIÓN
// ============================================================
async function disconnectSession(instanceId) {
    const inst = instances[instanceId];
    if (!inst) {
        console.log(`⚠️ Instancia ${instanceId} no existe en memoria`);
        return;
    }

    console.log(`🔧 Desconectando ${instanceId}...`);

    try {
        if (inst.sock && typeof inst.sock.logout === 'function') {
            await inst.sock.logout();
        } else if (inst.sock && typeof inst.sock.end === 'function') {
            await inst.sock.end(new Error('Manual disconnect'));
        }
    } catch (err) {
        console.log(`⚠️ Error al cerrar socket ${instanceId}: ${err.message}`);
    }

    delete instances[instanceId];
    console.log(`✅ Desconexión completada: ${instanceId}`);
}

// ============================================================
// DESCONECTAR TODAS (para shutdown limpio)
// ============================================================
async function disconnectAll() {
    console.log(`🔧 Desconectando todas las instancias...`);
    const ids = Object.keys(instances);
    for (const id of ids) {
        try {
            await disconnectSession(id);
        } catch (err) {
            console.error(`❌ Error desconectando ${id}: ${err.message}`);
        }
    }
    console.log(`✅ Todas las instancias desconectadas`);
}

// ============================================================
// OBTENER CLIENTE (SOCKET)
// ============================================================
function getClient(instanceId) {
    const inst = instances[instanceId];
    if (!inst) return null;
    return inst.sock;
}

// ============================================================
// VERIFICAR SI ESTÁ LISTA
// ============================================================
function isInstanceReady(instanceId) {
    const inst = instances[instanceId];
    return inst && inst.ready === true;
}

// ============================================================
// OBTENER NÚMERO DE LA INSTANCIA
// ============================================================
function getInstancePhone(instanceId) {
    const inst = instances[instanceId];
    return inst?.phoneNumber || null;
}

// ============================================================
// LISTAR TODAS LAS INSTANCIAS
// ============================================================
function getAllInstances() {
    return Object.keys(instances).map(id => ({
        instanceId: id,
        userId: instances[id].userId,
        ready: instances[id].ready,
        phoneNumber: instances[id].phoneNumber,
        hasQr: !!instances[id].qr
    }));
}

// ============================================================
// LISTAR INSTANCIAS DE UN USUARIO ESPECÍFICO (FIX PARA VIEWS.JS)
// ============================================================
function getUserInstances(userId) {
    return Object.keys(instances)
        .filter(id => instances[id].userId === userId)
        .map(id => ({
            instanceId: id,
            userId: instances[id].userId,
            ready: instances[id].ready,
            phoneNumber: instances[id].phoneNumber,
            hasQr: !!instances[id].qr
        }));
}

// ============================================================
// OBTENER QR PENDIENTE
// ============================================================
function getPendingQr(instanceId) {
    const inst = instances[instanceId];
    return inst?.qr || null;
}

// ============================================================
// RESTAURAR SESIONES AL INICIAR EL SERVIDOR
// ============================================================
async function restoreAllSessions() {
    console.log(`\n🔄 Restaurando sesiones Baileys...`);

    if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) {
        console.log('📂 No hay carpeta de sesiones Baileys aún.');
        return;
    }

    const folders = fs.readdirSync(BAILEYS_SESSIONS_DIR).filter(f => {
        const fullPath = path.join(BAILEYS_SESSIONS_DIR, f);
        return fs.statSync(fullPath).isDirectory();
    });

    if (folders.length === 0) {
        console.log('📂 No hay sesiones guardadas.');
        return;
    }

    console.log(`📂 Sesiones encontradas: ${folders.join(', ')}`);

    for (const folder of folders) {
        const instanceId = folder;
        const authDir = path.join(BAILEYS_SESSIONS_DIR, folder);

        const hasCreds = fs.readdirSync(authDir).some(f => 
            f.includes('creds') || f.includes('session') || f.includes('app-state')
        );

        if (!hasCreds) {
            console.log(`⚠️ ${instanceId}: carpeta vacía, saltando`);
            continue;
        }

        try {
            const userIdMatch = instanceId.match(/inst_(\d+)_/);
            const userId = userIdMatch ? userIdMatch[1] : 'unknown';

            console.log(`🔄 Restaurando ${instanceId} (userId: ${userId})...`);
            await startSession(instanceId, userId);
        } catch (err) {
            console.error(`❌ Error restaurando ${instanceId}: ${err.message}`);
        }
    }
}

// ============================================================
// EXPORTS
// ============================================================
module.exports = {
    setIO,
    startSession,
    disconnectSession,
    disconnectAll,
    getClient,
    isInstanceReady,
    getInstancePhone,
    getAllInstances,
    getUserInstances, // <-- FIX AGREGADO AQUÍ
    getPendingQr,
    restoreAllSessions
};
```

