const {
    makeWASocket,
    useMultiFileAuthState,
    DisconnectReason,
    fetchLatestBaileysVersion,
    isJidBroadcast,
    isJidStatusBroadcast
} = require('@whiskeysockets/baileys');
const { Boom } = require('@hapi/boom');
const pino = require('pino');
const fs = require('fs');
const path = require('path');

// ============================================================
// CONFIGURACIÓN
// ============================================================
const BAILEYS_SESSIONS_DIR = path.join(__dirname, '..', 'baileys_sessions');

if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) {
    fs.mkdirSync(BAILEYS_SESSIONS_DIR, { recursive: true });
}

// ============================================================
// ESTADO EN MEMORIA
// ============================================================
const instances = {}; 
const userSockets = new Map(); // Para compatibilidad con conversations.js
const activeInstances = new Map(); // Para compatibilidad con views.js

let io = null; 

// ============================================================
// INYECCIÓN DE SOCKET.IO
// ============================================================
function setIO(socketIO) {
    io = socketIO;
}

function emitToUser(userId, event, data) {
    if (!io) return;
    // Socket.io permite emitir a una "room" con el nombre del userId
    io.to(String(userId)).emit(event, data);
}

// ============================================================
// GESTIÓN DE SOCKETS DE USUARIO (Compatibilidad conversations.js)
// ============================================================
function registerSocket(userId, socketId) {
    const uid = String(userId);
    if (!userSockets.has(uid)) {
        userSockets.set(uid, new Set());
    }
    userSockets.get(uid).add(socketId);
}

function unregisterSocket(userId, socketId) {
    const uid = String(userId);
    if (userSockets.has(uid)) {
        userSockets.get(uid).delete(socketId);
        if (userSockets.get(uid).size === 0) {
            userSockets.delete(uid);
        }
    }
}

// ============================================================
// INSTANCIA ACTIVA (Compatibilidad views.js)
// ============================================================
function setActiveInstance(userId, instanceId) {
    activeInstances.set(String(userId), instanceId);
}

function getActiveInstance(userId) {
    return activeInstances.get(String(userId)) || null;
}

// ============================================================
// HELPERS
// ============================================================
