// ============================================================
function getClient(instanceId) {
    const inst = instances[instanceId];
    if (!inst) return null;
    return inst.sock;
}

// ============================================================
// VERIFICAR SI ESTÁ LISTA
// ============================================================
function isInstanceReady(instanceId) {
    const inst = instances[instanceId];
    return inst && inst.ready === true;
}

// ============================================================
// OBTENER NÚMERO DE LA INSTANCIA
// ============================================================
function getInstancePhone(instanceId) {
    const inst = instances[instanceId];
    return inst?.phoneNumber || null;
}

// ============================================================
// LISTAR TODAS LAS INSTANCIAS
// ============================================================
function getAllInstances() {
    return Object.keys(instances).map(id => ({
        instanceId: id,
        userId: instances[id].userId,
        ready: instances[id].ready,
        phoneNumber: instances[id].phoneNumber,
        hasQr: !!instances[id].qr
    }));
}

// ============================================================
// LISTAR INSTANCIAS DE UN USUARIO ESPECÍFICO
// ============================================================
function getUserInstances(userId) {
    const uid = String(userId);
    return Object.keys(instances)
        .filter(id => instances[id].userId === uid)
        .map(id => ({
            instanceId: id,
            userId: instances[id].userId,
            ready: instances[id].ready,
            phoneNumber: instances[id].phoneNumber,
            hasQr: !!instances[id].qr
        }));
}

// ============================================================
// RESUMEN DE INSTANCIAS DE UN USUARIO (FIX PARA CONVERSATIONS.JS)
// ============================================================
function getUserInstancesResumen(userId) {
    const uid = String(userId);
    return Object.keys(instances)
        .filter(id => instances[id].userId === uid)
        .map(id => ({
            instanceId: id,
            ready: instances[id].ready,
            phoneNumber: instances[id].phoneNumber,
            hasQr: !!instances[id].qr
        }));
}

// ============================================================
// OBTENER EL ID DE LA INSTANCIA ACTIVA DE UN USUARIO
// ============================================================
function getActiveInstanceId(userId) {
    return getActiveInstance(userId);
}

// ============================================================
// OBTENER ESTADO DE UNA INSTANCIA
// ============================================================
function getEstado(instanceId) {
    const inst = instances[instanceId];
    if (!inst) {
        return { ready: false, hasQr: false, phoneNumber: null, instanceId };
    }
    return {
        ready: inst.ready,
        hasQr: !!inst.qr,
        phoneNumber: inst.phoneNumber,
        instanceId: instanceId,
        userId: inst.userId
    };
}

// ============================================================
// OBTENER QR PENDIENTE
// ============================================================
function getPendingQr(instanceId) {
    const inst = instances[instanceId];
    return inst?.qr || null;
}

// ============================================================
// RESTAURAR SESIONES AL INICIAR EL SERVIDOR
// ============================================================
async function restoreAllSessions() {
    console.log(`\n🔄 Restaurando sesiones Baileys...`);

    if (!fs.existsSync(BAILEYS_SESSIONS_DIR)) {
        console.log('📂 No hay carpeta de sesiones Baileys aún.');
        return;
    }

    const folders = fs.readdirSync(BAILEYS_SESSIONS_DIR).filter(f => {
        const fullPath = path.join(BAILEYS_SESSIONS_DIR, f);
        return fs.statSync(fullPath).isDirectory();
    });

    if (folders.length === 0) {
        console.log('📂 No hay sesiones guardadas.');
        return;
    }

    console.log(`📂 Sesiones encontradas: ${folders.join(', ')}`);

    for (const folder of folders) {
        const instanceId = folder;
        const authDir = path.join(BAILEYS_SESSIONS_DIR, folder);

        const hasCreds = fs.readdirSync(authDir).some(f => 
            f.includes('creds') || f.includes('session') || f.includes('app-state')
        );

        if (!hasCreds) {
            console.log(`⚠️ ${instanceId}: carpeta vacía, saltando`);
            continue;
        }

        try {
            const userIdMatch = instanceId.match(/inst_(\d+)_/);
            const userId = userIdMatch ? userIdMatch[1] : 'unknown';

            console.log(`🔄 Restaurando ${instanceId} (userId: ${userId})...`);
            await startSession(instanceId, userId);
        } catch (err) {
            console.error(`❌ Error restaurando ${instanceId}: ${err.message}`);
        }
    }
}

// ============================================================
// EXPORTS
// ============================================================
module.exports = {
    setIO,
    startSession,
    disconnectSession,
    disconnectAll,
    getClient,
    isInstanceReady,
    getInstancePhone,
    getAllInstances,
    getUserInstances,
    getUserInstancesResumen, // <-- FIX AGREGADO AQUÍ
    getActiveInstanceId,
    getActiveInstance,
    setActiveInstance,
    getEstado,
    getPendingQr,
    restoreAllSessions,
    registerSocket,
    unregisterSocket
};
