```javascript
const express = require('express');
const router = express.Router();
const sessionManager = require('../services/session-manager');
const { cargarEstado, getEstadoInstancia, guardarEstadoSeguro } = require('../state/estado');
const { isAuthenticated } = require('./auth');

router.use(isAuthenticated);

// ─────────────────────────────────────────────
//  GET / — Panel principal
// ─────────────────────────────────────────────
router.get('/', async (req, res) => {
    try {
        const userId = req.session.userId;
        const instancias = sessionManager.getUserInstances(userId);
        let activeId = sessionManager.getActiveInstanceId(userId);

        // Auto-seleccionar la primera conectada si no hay activa
        if (!activeId && instancias.length > 0) {
            const conectada = instancias.find(i => i.ready) || instancias[0];
            sessionManager.setActiveInstance(userId, conectada.instanceId);
            activeId = conectada.instanceId;
        }

        // Forzar inicio si la instancia activa no está ready
        const activa = instancias.find(i => i.instanceId === activeId);
        if (activa && !activa.ready) {
            sessionManager.startSession(activeId, userId).catch(e => {
                console.error('Error iniciando instancia pendiente:', e.message);
            });
        }

        // FIX: getEstado requiere instanceId, no userId
        let estado = activeId ? sessionManager.getEstado(activeId) : null;

        if ((!estado || !estado.phoneNumber) && activeId) {
            const estadoDisco = cargarEstado(activeId);
            if (estadoDisco) {
                estado = { ...estado, ...estadoDisco };
            }
        }

        res.render('index', {
            estado: estado || null,
            instancias,
            activeId: activeId || null,
            sinInstancias: instancias.length === 0,
            userId: userId
        });
    } catch (error) {
        console.error('Error en GET /:', error);
        res.status(500).send('Error interno del servidor');
    }
});

// ─────────────────────────────────────────────
//  GET /qr
// ─────────────────────────────────────────────
router.get('/qr', (req, res) => {
    try {
        const userId = req.session.userId;
        const activeId = sessionManager.getActiveInstanceId(userId);
        const instancias = sessionManager.getUserInstances(userId);

        const hayPendiente = instancias.some(i => !i.ready);
        const activaConectada = instancias.find(i => i.instanceId === activeId && i.ready);

        if (activaConectada && !hayPendiente) {
            return res.redirect('/');
        }

        res.render('qr', {
            listo: false,
            userId: userId,
            activeId: activeId
