### Paso 1: Actualizar `routes/views.js` (Ruta GET /qr)

Buscá la ruta `GET /qr` y reemplazala por esta versión. Ahora pasa `activeId` a la plantilla y usa la propiedad correcta `.ready` de Baileys:

```javascript
// ─────────────────────────────────────────────
//  GET /qr
// ─────────────────────────────────────────────
router.get('/qr', (req, res) => {
    try {
        const userId = req.session.userId;
        const activeId = sessionManager.getActiveInstanceId(userId);
        const instancias = sessionManager.getUserInstances(userId);

        // En Baileys la propiedad es 'ready', no 'listo'
        const hayPendiente = instancias.some(i => !i.ready);
        const activaConectada = instancias.find(i => i.instanceId === activeId && i.ready);

        if (activaConectada && !hayPendiente) {
            return res.redirect('/');
        }

        res.render('qr', {
            listo: false,
            userId: userId,
            activeId: activeId // <-- FIX CRÍTICO: Pasamos activeId al frontend
        });
    } catch (error) {
        console.error('Error en GET /qr:', error);
        res.status(500).send('Error interno del servidor');
    }
});
```

