## Opción 1: Convertir en el Backend (Recomendada)

Reemplazá **solo la función `emitToUser`** en `services/session-manager.js` por esta versión que convierte el QR a imagen antes de enviarlo:

```javascript
function emitToUser(userId, event, data) {
    if (!io) {
        console.log(`[DEBUG emitToUser] ERROR: io no está definido`);
        return;
    }
    const uid = String(userId);
    console.log(`[DEBUG emitToUser] Emitiendo evento '${event}' a la sala principal: '${uid}'`);

    // FIX: Si es un evento QR y data.qr es un string (no base64), convertirlo a imagen
    if (event === 'qr' && data && data.qr && !data.qr.startsWith('data:image')) {
        const QRCode = require('qrcode');
        QRCode.toDataURL(data.qr).then(url => {
            data.qr = url; // Reemplazar el string por la imagen base64
            console.log(`[DEBUG emitToUser] QR convertido a imagen base64`);

            // Ahora emitir con la imagen convertida
            io.to(uid).emit(event, data);
            if (uid === '1788780543868') {
                io.to('543868').emit(event, data);
            }
            if (data.instanceId) {
                io.to(data.instanceId).emit(event, data);
            }
        }).catch(err => {
            console.error('❌ Error convirtiendo QR a imagen:', err);
        });
        return;
    }

    // Si no es QR o ya es base64, emitir normalmente
    io.to(uid).emit(event, data);
    if (uid === '1788780543868') {
        io.to('543868').emit(event, data);
    }
    if (data && data.instanceId) {
        io.to(data.instanceId).emit(event, data);
    }
}
```

