        // Generar QR usando la librería QRCode.js
        try {
            // Limpiar canvas anterior
            qrCanvas.innerHTML = '';
            qrImg.style.display = 'none';

            // Crear nuevo QR
            const qrCodeObj = new QRCode(qrCanvas, {
                text: data.qr,
                width: 260,
                height: 260,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.H
            });

            // Mostrar el canvas generado
            qrCanvas.style.display = 'block';
            statusMsg.textContent = '📷 Escaneá el QR con WhatsApp en tu celular';
            statusMsg.style.color = '#86efac';

            console.log('✅ [FRONTEND] QR generado correctamente');
