        }
        console.log(`🏷️ Rubro (celda D1): "${rubro}"`);

        //------------------------------------------------------
        // DETECTAR COLUMNAS (case-insensitive)
        //------------------------------------------------------
        const headers = Object.keys(datos[0] || {});
        console.log(`📋 Encabezados: ${headers.join(', ')}`);
        const headersLower = headers.map(h => ({
            original: h,
