Reemplazá **todo** el contenido de tu archivo `routes/views.js` por esta versión corregida y 100% compatible con Baileys. Esta versión fusiona correctamente el estado de conexión de la instancia con los datos de la campaña guardados en disco.

```javascript
const express = require('express');
const router = express.Router();
const sessionManager = require('../services/session-manager');
const { cargarEstado, guardarEstado } = require('../state/estado');
const { isAuthenticated } = require('./auth');

router.use(isAuthenticated);

// Función auxiliar para fusionar el estado de conexión con el estado de la campaña en disco
function obtenerEstadoCompleto(activeId) {
    if (!activeId) return null;

    const estadoDisco = cargarEstado(activeId) || {};
    const infoInst = sessionManager.getEstado(activeId);

    return {
        ...estadoDisco,
        listo: infoInst ? infoInst.ready : false,
        numeroWhatsApp: infoInst ? infoInst.phoneNumber : (estadoDisco.numeroWhatsApp || '')
    };
}

