### ✅ La Solución Definitiva (2 Pasos)

Vamos a hacer que el backend guarde automáticamente cada respuesta y agregamos el endpoint que falta para borrarlas.

#### Paso 1: Modificar `services/session-manager.js`
Reemplazá el bloque `sock.ev.on('messages.upsert', ...)` por esta versión mejorada. Ahora busca el nombre del contacto, guarda la conversación en el disco y avisa al frontend en tiempo real:

```javascript
    sock.ev.on('messages.upsert', async ({ messages, type }) => {
        if (type !== 'notify') return;
        for (const msg of messages) {
            if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid)) continue;
            if (msg.key.fromMe) continue;
            if (!msg.message) continue;

            const fromJid = msg.key.remoteJid;
            const numeroLimpio = fromJid.split('@')[0]; // Ej: 5493517460660
            const text = msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.message?.imageMessage?.caption || '';

            console.log(`💬 Mensaje recibido de ${numeroLimpio}: "${text.substring(0, 50)}"`);
            emitToUser(userId, 'message_received', { instanceId, from: fromJid, text, timestamp: msg.messageTimestamp });

            // ✅ FIX: Guardar automáticamente en el estado de conversaciones
            try {
                const { getEstadoInstancia, guardarEstadoSeguro } = require('../state/estado');
                const estado = getEstadoInstancia(instanceId);

                if (estado) {
                    if (!Array.isArray(estado.conversaciones)) estado.conversaciones = [];

                    // Buscar nombre en contactos cargados
                    const contacto = (estado.contactosCargados || []).find(c => 
                        (c.numero && c.numero.includes(numeroLimpio)) || 
                        (c.NUMERO && c.NUMERO.includes(numeroLimpio))
                    );
                    const nombre = contacto ? (contacto.nombre || contacto.NOMBRE) : numeroLimpio;
                    const fechaStr = new Date(msg.messageTimestamp * 1000).toISOString();

                    // Buscar si ya existe para actualizar, o crear nueva
                    let conv = estado.conversaciones.find(c => c.numero === numeroLimpio);

                    const nuevaConv = {
                        id: conv ? conv.id : `conv_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                        numero: numeroLimpio,
