            instances[instanceId].ready = false;
            instances[instanceId].reconnectAttempts = (instances[instanceId].reconnectAttempts || 0) + 1;
            const shouldReconnect = ![DisconnectReason.loggedOut, DisconnectReason.forbidden, DisconnectReason.unavailableService].includes(statusCode);

            if (shouldReconnect && instances[instanceId].reconnectAttempts < 10) {
