emitToUser(userId, 'qr', { instanceId, qr });
}

if (connection === 'close') {
const statusCode = (lastDisconnect?.error instanceof Boom)?.output?.statusCode;
const reason = lastDisconnect?.error?.output?.payload?.message || 'Desconocido';
console.log(`❌ Conexión cerrada para ${instanceId}. Motivo: ${reason} (código: ${statusCode})`);

if (statusCode === DisconnectReason.loggedOut || statusCode === 401) {
console.log(`🗑️ Sesión ${instanceId} cerrada por logout. Borrando credenciales.`);
try { fs.rmSync(authDir, { recursive: true, force: true }); } catch (e) {}
instances[instanceId].ready = false;
instances[instanceId].qr = null;
emitToUser(userId, 'disconnected', { instanceId, reason: 'logged_out' });
delete instances[instanceId];
return;
}

instances[instanceId].ready = false;
instances[instanceId].reconnectAttempts = (instances[instanceId].reconnectAttempts || 0) + 1;
const shouldReconnect = ![DisconnectReason.loggedOut, DisconnectReason.forbidden, DisconnectReason.unavailableService].includes(statusCode);

if (shouldReconnect && instances[instanceId].reconnectAttempts < 10) {
const delay = Math.min(5000 * instances[instanceId].reconnectAttempts, 60000);
console.log(`🔄 Reconectando ${instanceId} en ${delay}ms...`);
emitToUser(userId, 'disconnected', { instanceId, reason: 'reconnecting', delay });
setTimeout(() => { if (instances[instanceId]) startSession(instanceId, userId); }, delay);
} else {
console.log(`🛑 No se reconectará ${instanceId}`);
emitToUser(userId, 'disconnected', { instanceId, reason: 'fatal' });
}
}

if (connection === 'open') {
const phoneNumber = parsePhoneNumberFromJid(sock.user?.id);
instances[instanceId].ready = true;
instances[instanceId].qr = null;
instances[instanceId].phoneNumber = phoneNumber;
instances[instanceId].reconnectAttempts = 0;
console.log(`\n✅ WHATSAPP READY (Baileys)`);
console.log(`Instancia: ${instanceId}`);
console.log(`Número: ${phoneNumber}`);
console.log(`================================\n`);
emitToUser(userId, 'ready', { instanceId, phoneNumber });
}
});

// ✅ NUEVO: Detección de INFO + Notificación al usuario + Guardar conversación
sock.ev.on('messages.upsert', async ({ messages, type }) => {
if (type !== 'notify') return;
for (const msg of messages) {
if (isJidBroadcast(msg.key.remoteJid) || isJidStatusBroadcast(msg.key.remoteJid) || msg.key.fromMe || !msg.message) continue;

const from = msg.key.remoteJid;
