                                  `🏷️ *Rubro:* ${rubro}\n` +
                                  `💬 *Mensaje:* "${text}"\n\n` +
                                  `⏰ ${new Date().toLocaleString('es-AR')}`;

                    console.log(`[DEBUG] Enviando notificación al admin: ${jidAdmin}`);
