                    const numeroRealConv = contactoConv ? (contactoConv.numero || contactoConv.NUMERO) : numeroJidConv;
                    const nombreConv = contactoConv ? (contactoConv.nombre || contactoConv.NOMBRE) : numeroRealConv;

                    let conv = estado.conversaciones.find(c => c.numero === numeroRealConv);
                    const nuevaConv = {
                        id: conv ? conv.id : `conv_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                        numero: numeroRealConv,
