        if (tipoCampana !== undefined) estado.tipoCampana = (tipoCampana || '').trim();
        if (respuestasInfoPorTipo && typeof respuestasInfoPorTipo === 'object') estado.respuestasInfoPorTipo = respuestasInfoPorTipo;
